function applyOrderBy(qb: any, orderBy?: OrderBy[]): any {
  if (!orderBy || orderBy.length === 0) return qb;
  let builder = qb;
  for (const order of orderBy) {
    builder = builder.orderBy(order.field, order.direction);
  }
  return builder;
}

