        {
          attempt,
          status: response.status,
          retryAfterHeader: response.headers.get("retry-after")
        },
        this.retryPolicy
      );

      if (!decision.retry) {
        return response;
      }

      await this.sleep(decision.delayMs);
      attempt += 1;
    }
