import type { Adapter, KVStoreAdapter } from '@superfunctions/db';

export { KVStoreAdapter };

export type LegacyWindowAlgorithm = 'sliding-window'|'fixed-window';
export type RateLimitAlgorithm = LegacyWindowAlgorithm | 'token-bucket';

export interface RateLimitConfig {
  windowMs: number;
  maxRequests: number;
  keyPrefix?: string;
  persistence?: Adapter | KVStoreAdapter;
  algorithm?: RateLimitAlgorithm;
  now?: () => number;
}

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetAt: string; // ISO8601
  total: number;
}

export interface CheckLimitInput {
  key: string;
  windowSeconds?: number;
  limit?: number;
}

export interface CheckManyLimitsInput {
  keys: string[];
  windowSeconds?: number;
  limit?: number;
}

export interface RateLimitManyResult {
  allowed: boolean;
  remainingByKey: Map<string, number>;
  resetAtByKey: Map<string, string>;
  resetAt: string;
  total: number;
}

export interface RateLimiter {
  check(input: CheckLimitInput): Promise<RateLimitResult>;
  checkMany(input: CheckManyLimitsInput): Promise<RateLimitManyResult>;
  reset(key: string): Promise<void>;
}

interface KVSetInput {
  key: string;
  value: string;
  ttlSeconds?: number;
}

interface FixedWindowState {
  count: number;
  windowStart: number;
  expiresAt?: number;
}

interface SlidingWindowState {
  timestamps: number[];
  expiresAt?: number;
}

interface TokenBucketState {
  tokens: number;
  lastRefill: number;
  expiresAt?: number;
}

function createInMemoryKVStore(now: () => number = Date.now): KVStoreAdapter {
  const store = new Map<string, { value: string; expiresAt?: number }>();

  return {
    async get(key: string): Promise<string | null> {
      const entry = store.get(key);
      if (!entry) return null;
      if (entry.expiresAt && now() > entry.expiresAt) {
        store.delete(key);
        return null;
      }
      return entry.value;
    },
    async set(input: { key: string; value: string; ttlSeconds?: number }): Promise<void> {
      store.set(input.key, {
        value: input.value,
        expiresAt: input.ttlSeconds ? now() + input.ttlSeconds * 1000 : undefined,
      });
    },
    async delete(key: string): Promise<void> {
      store.delete(key);
    },
  };
}

function isAdapter(p: unknown): p is Adapter {
  return !!p && typeof p === 'object' && 'findOne' in p && 'create' in p;
}

function ensureKV(p: Adapter | KVStoreAdapter, now: () => number): KVStoreAdapter {
  if (isAdapter(p)) {
    return {
      async get(key: string) {
        const res = await p.findOne<{ value: string; expiresAt?: string }>({
          model: 'rate_limits',
          where: [{ field: 'key', operator: 'eq', value: key }],
        });
        if (!res) return null;
        ],
        namespace: 'filefn',
      });

      const result = await processing.runProcessing(
        {
          fileId: 'file_001',
          versionId: 'ver_001',
          storageKey: 'uploads/file_001/ver_001-image.png',
          mimeType: 'image/png',
          size: 3,
          fileName: 'image.png',
          tenantId: 'org_123',
        },
        { principalId: 'user_123', tenantId: 'org_123', requestId: 'req_artifact_route' },
      );

      expect(result.artifactsCreated).toBe(1);
      expect(storageCalls).toContain('durable-bucket:download-stream:uploads/file_001/ver_001-image.png');
      expect(storageCalls).toContain('temporary-bucket:upload-stream:uploads/file_001/ver_001-image.png.thumb.png');
    });
  });

  describe('Download rate limiting', () => {
    it('should enforce rate limits on download (TV-RATE-NEG-001 download variant)', async () => {
      const { fileId } = await createFileViaUpload(fileFn, db, storageSizes, 'user_123');

      const rateLimiter = {
        async check(_input: any) {
          return { allowed: false, remaining: 0, resetAt: new Date(Date.now() + 60000).toISOString(), total: 10 };
        },
        async checkMany(input: { keys: string[] }) {
          const resetAt = new Date(Date.now() + 60000).toISOString();
          return {
            allowed: false,
            remainingByKey: new Map(input.keys.map(key => [key, 0])),
            resetAtByKey: new Map(input.keys.map(key => [key, resetAt])),
            resetAt,
            total: 10,
          };
        },
        async reset(_key: string) {},
      };

      const fileFnWithRateLimit = createFileFn({
        db,
        storage: createFakeStorageAdapter({
          capabilities: { signedUploadUrls: true, signedDownloadUrls: true, multipart: true, proxyStreamingUpload: false, proxyStreamingDownload: true },
        }),
        policies: [{ name: 'user-avatar', contentTypes: ['image/png'] }],
        rateLimiter,
        auth: { required: false },
      });

      const request = new Request(`http://localhost/${fileId}/download`, {
        method: 'GET',
        headers: { 'x-request-id': 'req_rate' },
      });

      const response = await fileFnWithRateLimit.router.handle(request);
      expect(response!.status).toBe(429);

      const body = await response!.json();
      expect(body.error.code).toBe('FILEFN_RATE_LIMITED');
    });

