      ).rejects.toThrow(NamespaceRequiredError);
      await expect(
        db.delete({ model: 'task', where: [] }),
      ).rejects.toThrow(NamespaceRequiredError);
      await expect(
        db.deleteMany({ model: 'task', where: [] }),
      ).rejects.toThrow(NamespaceRequiredError);
      await expect(
