      const result = await db.findOne({
        model: 'task',
        where: [{ field: 'id', operator: 'eq', value: 't1' }],
        namespace: 'user:A',
      });

      expect(result).toEqual({ id: 't1', title: 'Test' });
      expect(result).not.toHaveProperty('__ns');
    });

    it('strips __ns from update result', async () => {
      await db.create({
        model: 'task',
        data: { id: 't1', title: 'Old' },
