import { describe, expect, it, vi } from "vitest";
import { createRouter } from "@superfunctions/http";
import type {
  OAuthFlowCallbackResult,
  OAuthFlowConnectionCleanup,
  OAuthFlowDisconnectResult,
  OAuthFlowService,
  OAuthFlowStartResult
} from "@superfunctions/oauth-flow";
import { createOAuthBrowserRoutes, createOAuthConnectionRoutes } from "../index.js";

function createFlowServiceMocks() {
  const start = vi.fn(async () => ({
    providerId: "google",
    authorizationUrl: "https://accounts.google.example/auth?state=st_01",
    stateId: "st_01",
    expiresAt: "2026-01-01T00:10:00.000Z"
  } satisfies OAuthFlowStartResult));

  const handleCallback = vi.fn(async () => ({
    providerId: "google",
    subject: {
      kind: "browser-auth",
      intentId: "intent_01",
      returnTo: "https://app.example/post-auth"
    },
    tokenSet: {
      accessToken: "access_01"
    }
  } satisfies OAuthFlowCallbackResult));

  const disconnect = vi.fn(async () => ({
    disconnected: true,
    remoteRevokeAttempted: true,
    localTokenDeleted: true,
    connectionCleanup: {
      attempted: true,
      deleted: true,
      reason: "deleted"
    } satisfies OAuthFlowConnectionCleanup,
    connectionDeleted: true
  } satisfies OAuthFlowDisconnectResult));

  const refresh = vi.fn(async () => ({
    accessToken: "access_refreshed"
  }));

  return {
    service: {
      start,
      handleCallback,
      disconnect,
      refresh
    } satisfies OAuthFlowService,
    start,
  returnTo: string,
  request: Request,
  allowedRedirectOrigins?: string[]
): string {
  const requestUrl = new URL(request.url);
  const fallback = new URL("/", requestUrl).toString();

  let target: URL;
  try {
    // Resolve relative URLs against the request origin; absolute URLs are
    // parsed as-is so their origin can be checked.
    target = new URL(returnTo, requestUrl);
  } catch {
    return fallback;
  }

  // Only http(s) targets are ever acceptable (blocks javascript:, data:, etc.).
  if (target.protocol !== "http:" && target.protocol !== "https:") {
    return fallback;
  }

  if (target.origin === requestUrl.origin) {
    return target.toString();
  }

  const allowed = new Set(
    (allowedRedirectOrigins ?? [])
      .map((origin) => {
        try {
          return new URL(origin).origin;
        } catch {
          return null;
        }
      })
      .filter((origin): origin is string => origin !== null)
  );

  if (allowed.has(target.origin)) {
    return target.toString();
  }

  return fallback;
}

