        }
        const issued = await issueSession(ctx.config, ctx.hooks, {
          request,
          userId: result.user.id,
          primaryEmail: result.user.primaryEmail,
          methods: ['password']
        });
        const response = buildSessionResponse(issued, body.sessionMode);

