  return isRealCommit(commitish) && gitOk(["cat-file", "-e", `${commitish}^{commit}`]);
}

function resolveDiffBase(event) {
  const eventName = process.env.GITHUB_EVENT_NAME || "local";
  const defaultBranch = event.repository?.default_branch || "dev";

