    getByIdentifier(identifier) {
      return call<AuthFnRegionLookupRecord | null>('getByIdentifier', identifier);
    },

    putIfAbsent(record) {
      return call<{
        inserted: boolean;
        existing?: AuthFnRegionLookupRecord;
