  console.log(`client origin allowed: ${CLIENT_ORIGIN}`);

  const shutdown = async () => {
    await started.close();
    await server.close();
    process.exit(0);
  };

  process.once('SIGINT', () => void shutdown());
  process.once('SIGTERM', () => void shutdown());
