        return json({
          ok: true,
          data: existing ?? null,
        } satisfies LookupResponse<AuthFnRegionLookupRecord | null>);
      }

      case 'putIfAbsent': {
        const record = requireRecord(body.record);
        const existing = await this.state.storage.get<AuthFnRegionLookupRecord>('record');
