        } catch (error) {
          if (!isConflictError(error)) throw error;
          return {
            ok: false,
            code: "CONFLICT",
            message: "Record already exists",
            path: "id",
          };
        }
        const propagationChanges = await collectPropagationChanges(
          targetDb,
          [{ resource: mut.resource, id: mut.id }],
        );
