  private tail: Promise<void> = Promise.resolve();
  private pendingCount = 0;

  async runExclusive<T>(task: () => Promise<T>): Promise<T> {
    this.pendingCount += 1;
    const previous = this.tail;
    let release!: () => void;
    this.tail = new Promise<void>((resolve) => {
      release = resolve;
    });

    await previous.catch(() => undefined);

