      const current1 = await store.getCurrent("test-namespace");
      expect(current1).toBe(0);

      await store.getNext("test-namespace");
      await store.getNext("test-namespace");
      const current2 = await store.getCurrent("test-namespace");
      expect(current2).toBe(2);
    });
