    vi.spyOn(ChangeTrackingService.prototype, "getCurrentServerSeq").mockResolvedValue(0);

    const result = await executePush(
      {
        clientId: "c1",
        mutations: [
          {
            clientId: "c1",
            mutationId: "m-replace",
            resource: "tasks",
            operation: "replace",
            id: "t-replace",
