    await expect(
      client.exchangeToken({
        provider: googleProvider,
        grantType: "authorization_code",
        clientId: "client-id",
        clientSecret: "client-secret",
        code: "code-fail",
        redirectUri: "https://app/callback"
      })
    ).rejects.toMatchObject({
      code: "OAUTH_TOKEN_EXCHANGE_FAILED",
