<details>
<summary>♻️ Proposed helper</summary>

```ts
function normalizeHostname(hostname: string): string {
  let value = hostname;
  if (value.startsWith('[')) {
    value = value.slice(1);
  }
  if (value.endsWith(']')) {
    value = value.slice(0, -1);
  }
  while (value.endsWith('.')) {
    value = value.slice(0, -1);
  }
  return value.toLowerCase();
}
```
