// ─── Shared helpers ──────────────────────────────────────────────────────────

function makeInternalApi(overrides?: any) {
  return {
    ensureTable: vi.fn(async () => {}),
    findOne: vi.fn(async () => null),
    findMany: vi.fn(async () => []),
    create: vi.fn(async (_table: string, data: any) => data),
