/**
 * Parse library initialization files and extract configs
 * 
 * This parses TypeScript/JavaScript files to find library initialization calls
 * (e.g., createConductBackend, createAuthFn) and extracts the config objects
 * passed to them.
 */

import * as ts from 'typescript';
import fs from 'node:fs';
import type { PackageRegistry } from './discover-packages.js';

export interface ParsedLibraryInit {
  libraryName: string;
  packageName: string;
  functionName: string;
  config: any;
  location: { line: number; column: number };
}

/**
 * Parse a file and extract library initialization calls
 */
export function parseLibraryInitializations(
  filePath: string,
  registry: PackageRegistry
): ParsedLibraryInit[] {
  const content = fs.readFileSync(filePath, 'utf-8');
  const sourceFile = ts.createSourceFile(
    filePath,
    content,
    ts.ScriptTarget.Latest,
    true
  );

  const results: ParsedLibraryInit[] = [];

  function visit(node: ts.Node) {
    if (ts.isCallExpression(node)) {
      const functionName = node.expression.getText(sourceFile);

      if (functionName in registry) {
        const configArg = node.arguments[0];
        if (configArg) {
          try {
            // Extract config object
            const config = extractConfigObject(configArg, sourceFile);

            const registryEntry = registry[functionName];
            const packageName =
              typeof registryEntry === 'string' ? registryEntry : registryEntry.packageName;
            const libraryName =
              typeof registryEntry === 'string'
                ? packageName.split('/').pop()!.replace('@superfunctions/', '')
                : registryEntry.libraryName;

            const { line, character } = sourceFile.getLineAndCharacterOfPosition(node.getStart());

            results.push({
              libraryName,
              packageName,
              functionName,
              config,
              location: { line: line + 1, column: character + 1 },
            });
          } catch (e: any) {
            console.warn(`⚠️  Could not extract config from ${functionName} call: ${e.message}`);
          }
        }
      }
    }

    ts.forEachChild(node, visit);
  }

  visit(sourceFile);
  return results;
}

function extractConfigObject(node: ts.Node, sourceFile: ts.SourceFile): any {
  if (ts.isAsExpression(node) || ts.isSatisfiesExpression(node) || ts.isTypeAssertionExpression(node)) {
    return extractConfigObject(node.expression, sourceFile);
  }

  // Handle direct object literals
  if (ts.isObjectLiteralExpression(node)) {
    return parseObjectLiteral(node, sourceFile);
  }

  // Handle variable references
  if (ts.isIdentifier(node)) {
    // Try to resolve the variable
    const varName = node.text;
    const resolved = resolveVariable(varName, sourceFile);
    if (resolved) {
      return extractConfigObject(resolved, sourceFile);
    }
    throw new Error(`Cannot resolve variable: ${varName}`);
  }

  // Handle spread operators
  if (ts.isSpreadElement(node)) {
    return extractConfigObject(node.expression, sourceFile);
  }

  throw new Error('Config must be an object literal or resolvable variable');
}

function parseObjectLiteral(node: ts.ObjectLiteralExpression, sourceFile: ts.SourceFile): any {
  const obj: any = {};

  for (const prop of node.properties) {
    if (ts.isPropertyAssignment(prop)) {
      const key = getPropertyName(prop.name);
      if (key) {
        obj[key] = evaluateExpression(prop.initializer, sourceFile);
      }
    } else if (ts.isShorthandPropertyAssignment(prop)) {
      const key = prop.name.text;
      // For shorthand properties, we can't easily resolve the value
      // Mark as undefined to indicate it needs runtime resolution
      obj[key] = undefined;
    } else if (ts.isSpreadAssignment(prop)) {
      // Handle spread in object literal
      const spreadValue = evaluateExpression(prop.expression, sourceFile);
      if (typeof spreadValue === 'object' && spreadValue !== null) {
        Object.assign(obj, spreadValue);
      }
    }
  }

  return obj;
}

function getPropertyName(name: ts.PropertyName): string | null {
  if (ts.isIdentifier(name)) {
    return name.text;
  }
  if (ts.isStringLiteral(name)) {
    return name.text;
  }
  if (ts.isNumericLiteral(name)) {
    return name.text;
  }
  return null;
}

function evaluateExpression(node: ts.Node, sourceFile: ts.SourceFile): any {
  // Primitives
  if (ts.isStringLiteral(node)) {
    return node.text;
  }
  if (ts.isNumericLiteral(node)) {
    return Number(node.text);
  }
  if (node.kind === ts.SyntaxKind.TrueKeyword) {
    return true;
  }
  if (node.kind === ts.SyntaxKind.FalseKeyword) {
    return false;
  }
  if (node.kind === ts.SyntaxKind.NullKeyword) {
    return null;
  }
  if (node.kind === ts.SyntaxKind.UndefinedKeyword) {
    return undefined;
  }

  // Object literals
  if (ts.isObjectLiteralExpression(node)) {
    return parseObjectLiteral(node, sourceFile);
  }

  // Arrays
  if (ts.isArrayLiteralExpression(node)) {
    return node.elements.map(el => evaluateExpression(el, sourceFile));
  }

  // Identifiers (variable references)
  if (ts.isIdentifier(node)) {
    const varName = node.text;
    const resolved = resolveVariable(varName, sourceFile);
    if (resolved) {
      return evaluateExpression(resolved, sourceFile);
    }
    // Cannot resolve - return placeholder
    return undefined;
  }

  // Property access (e.g., process.env.DATABASE_URL)
  if (ts.isPropertyAccessExpression(node)) {
    // For now, mark as undefined - runtime values
    return undefined;
  }

  // Template literals
  if (ts.isTemplateExpression(node) || ts.isNoSubstitutionTemplateLiteral(node)) {
    // Cannot evaluate template literals statically
    return undefined;
  }

  // Function calls (e.g., plugin() calls)
  if (ts.isCallExpression(node)) {
    // Return placeholder object indicating it's a function call
    const fnName = node.expression.getText(sourceFile);
    return {
      __functionCall: fnName,
      __args: node.arguments.map((arg) => evaluateExpression(arg, sourceFile))
    };
  }

  // Arrow functions
  if (ts.isArrowFunction(node) || ts.isFunctionExpression(node)) {
    return { __function: true };
  }

  // For everything else, return undefined
  return undefined;
}

/**
 * Discover superfunctions libraries in node_modules
 *
 * Scans installed packages for those with superfunctions metadata
 * in their package.json, building a dynamic registry of initialization
 * functions.
 */

import fs from "node:fs";
import path from "node:path";

export interface SuperfunctionsPackageMetadata {
  packageName: string;
  initFunction: string;
  schemaVersion?: number;
  libraryNames: string[];
}

export interface PackageRegistry {
  [initFunction: string]:
    | string
    | {
        packageName: string;
        libraryName: string;
      };
}

/**
 * Discover all superfunctions libraries in node_modules
 */
export function discoverSuperfunctionsPackages(
  cwd: string = process.cwd()
): SuperfunctionsPackageMetadata[] {
  const nodeModulesPaths = findNodeModulesPaths(cwd);
  const discovered: SuperfunctionsPackageMetadata[] = [];
  const seenPackageNames = new Set<string>();

  for (const nodeModulesPath of nodeModulesPaths) {
    scanDirectory(nodeModulesPath, discovered, seenPackageNames);
  }

  return discovered;
}

export function findNodeModulesPaths(startDir: string): string[] {
  const paths: string[] = [];
  let currentDir = path.resolve(startDir);

  while (true) {
    const nodeModulesPath = path.join(currentDir, "node_modules");
    if (fs.existsSync(nodeModulesPath)) {
      paths.push(nodeModulesPath);
    }

    const parentDir = path.dirname(currentDir);
    if (parentDir === currentDir) {
      return paths;
    }

    currentDir = parentDir;
  }
}

export function findNearestNodeModulesPath(startDir: string): string | null {
  return findNodeModulesPaths(startDir)[0] ?? null;
}

/**
 * Build a registry map from discovered packages
 */
export function buildRegistry(
  packages: SuperfunctionsPackageMetadata[]
): PackageRegistry {
  const registry: PackageRegistry = {};

  for (const pkg of packages) {
    registry[pkg.initFunction] = {
      packageName: pkg.packageName,
      libraryName: pkg.libraryNames[0] ?? deriveLibraryNames(pkg.packageName)[0] ?? pkg.packageName
    };
  }

  return registry;
}

function scanDirectory(
  dir: string,
  discovered: SuperfunctionsPackageMetadata[],
  seenPackageNames: Set<string> = new Set()
): void {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const entryPath = path.join(dir, entry.name);

    // Check for directory or symlink to directory
    let isDir = entry.isDirectory();
    if (entry.isSymbolicLink()) {
      try {
        const stats = fs.statSync(entryPath);
        isDir = stats.isDirectory();
      } catch (e) {
        // Ignore broken symlinks
        isDir = false;
      }
    }

    if (!isDir) continue;

    // Handle scoped packages (@superfunctions/authfn, etc.)
    if (entry.name.startsWith("@")) {
      scanDirectory(entryPath, discovered, seenPackageNames);
      continue;
    }

    // Check for package.json
    const packageJsonPath = path.join(entryPath, "package.json");
    if (fs.existsSync(packageJsonPath)) {
      try {
        const packageJson = JSON.parse(
          fs.readFileSync(packageJsonPath, "utf-8")
        );

        // Check for superfunctions metadata
        if (
          packageJson.superfunctions &&
          packageJson.superfunctions.initFunction
        ) {
          const packageName = String(packageJson.name ?? entry.name);
          if (seenPackageNames.has(packageName)) {
            continue;
          }
          seenPackageNames.add(packageName);

          discovered.push({
            packageName,
            initFunction: packageJson.superfunctions.initFunction,
            schemaVersion: packageJson.superfunctions.schemaVersion,
            libraryNames: deriveLibraryNames(
              packageName,
              packageJson.superfunctions.libraryNames,
              packageJson.superfunctions.namespace,
            ),
          });
        }
      } catch (e) {
        // Skip malformed package.json files
        continue;
      }
    }
  }
}

/**
 * Get registry for use in parser
 * This is the main export that replaces the hardcoded LIBRARY_REGISTRY
 */
export function getSuperfunctionsRegistry(
  cwd: string = process.cwd()
): PackageRegistry {
  const packages = discoverSuperfunctionsPackages(cwd);
  return buildRegistry(packages);
}

function deriveLibraryNames(
  packageName: string,
  explicitLibraryNames?: unknown,
  explicitNamespace?: unknown,
): string[] {
  if (Array.isArray(explicitLibraryNames)) {
    const normalized = explicitLibraryNames
      .filter((value): value is string => typeof value === "string" && value.trim().length > 0)
      .map((value) => value.trim());
    if (normalized.length > 0) {
      return [...new Set(normalized)];
    }
  }

  if (typeof explicitNamespace === "string" && explicitNamespace.trim().length > 0) {
    return [explicitNamespace.trim()];
  }

  if (packageName.startsWith("@superfunctions/")) {
    return [packageName.slice("@superfunctions/".length)];
  }

  if (packageName.startsWith("@")) {
    const [scope, name] = packageName.split("/");
    if (scope && name) {
      const scopeName = scope.slice(1);
      if (name === "core") {
        return [scopeName];
      }

      return [name];
    }
  }

  return [packageName];
}
