    const disabled = await client.disableTwoFactor({
      code: generateTotp(enrollment.data.secret, clock.now())
    });
    expect(disabled.ok).toBe(true);
    if (disabled.ok) {
      expect(disabled.data.disabled).toBe(true);
    }
  });

