  const candidates = [
    './schema.datafn.ts',
    './src/schema.datafn.ts',
    './schema.json',
    './src/schema.json',
  ];

  for (const candidate of candidates) {
    const fullPath = resolve(candidate);
    if (existsSync(fullPath)) {
      console.log(`✓ Found schema: ${candidate}`);
      return fullPath;
