export function createObservability<TEvent extends ObservationEvent = ObservationEvent>(
  input: Exclude<ObservabilityInput<TEvent>, false | null | undefined> = {},
): SuperfunctionObservability<TEvent> {
  if (isSuperfunctionObservability<TEvent>(input)) {
    return input;
  }

  if (isLogger(input)) {
    return new SuperfunctionObservabilityImpl<TEvent>({
      logger: input,
      labels: {},
    });
  }

  return new SuperfunctionObservabilityImpl<TEvent>({
    service: input.service,
    component: input.component,
    logger: input.logger,
    labels: input.labels ?? {},
    events: normalizeEventChannel(input.events),
    metrics: normalizeMetricChannel(input.metrics),
    requestContext: input.requestContext,
  });
}

export function normalizeObservability<TEvent extends ObservationEvent = ObservationEvent>(
  input: ObservabilityInput<TEvent>,
): SuperfunctionObservability<TEvent> | undefined {
  if (!input) {
    return undefined;
  }
  return createObservability(input as Exclude<ObservabilityInput<TEvent>, false | null | undefined>);
}

export function instrumentMethods<TTarget extends object>(
  input: InstrumentMethodsInput<TTarget>,
): TTarget {
  const { target, observability, kind, component, extract } = input;
  if (!observability) {
    return target;
  }

  return new Proxy(target, {
    get(currentTarget, property, receiver) {
      const value = Reflect.get(currentTarget, property, receiver);
      if (typeof value !== "function") {
        return value;
      }

      return async (...args: unknown[]) => {
        const extracted = extract?.({ property, args }) ?? {};
        const startedAt = now();
        try {
          const result = await value.apply(currentTarget, args);
          observability.metrics.record({
            kind,
            component,
            operation: extracted.operation ?? String(property),
            resource: extracted.resource,
            labels: extracted.labels,
            durationMs: now() - startedAt,
            ok: true,
          });
          return result;
        } catch (error) {
          observability.metrics.record({
            kind,
            component,
            operation: extracted.operation ?? String(property),
            resource: extracted.resource,
            labels: extracted.labels,
            durationMs: now() - startedAt,
            ok: false,
          });
          throw error;
        }
      };
    },
  }) as TTarget;
}

export function readObservationGroup(
  snapshot: RequestObservationSnapshot | undefined,
  kind: string,
): ObservationGroupSnapshot {
  return snapshot?.groups[kind] ?? {
    kind,
    count: 0,
    durationMs: 0,
    maxDurationMs: 0,
    errorCount: 0,
  };
}

export function roundObservationMs(value: number): number {
  return Math.round(value * 100) / 100;
}

function isSuperfunctionObservability<TEvent extends ObservationEvent>(
  value: unknown,
): value is SuperfunctionObservability<TEvent> {
  return Boolean(value) &&
    typeof value === "object" &&
    typeof (value as SuperfunctionObservability).startRequest === "function" &&
    typeof (value as SuperfunctionObservability).runWithRequest === "function" &&
    typeof (value as SuperfunctionObservability).events === "object" &&
    typeof (value as SuperfunctionObservability).metrics === "object";
}

function isLogger(value: unknown): value is ObservationLogger {
  return Boolean(value) &&
    typeof value === "object" &&
    (
      typeof (value as ObservationLogger).info === "function" ||
      typeof (value as ObservationLogger).debug === "function" ||
      typeof (value as ObservationLogger).warn === "function" ||
      typeof (value as ObservationLogger).error === "function"
    );
}

function normalizeEventChannel<TEvent extends ObservationEvent>(
  events: ObservabilityConfigInput<TEvent>["events"],
): ObservationEventChannel<TEvent> | undefined {
  if (!events) {
    return undefined;
  }
  return typeof events === "function" ? { emit: events } : events;
}

function normalizeMetricChannel(
  metrics: ObservabilityConfigInput["metrics"],
): ObservationMetricChannel | undefined {
  if (!metrics) {
    return undefined;
  }
  return typeof metrics === "function" ? { record: metrics } : metrics;
}

function createStackRequestContext<TEvent extends ObservationEvent>(): RequestObservationContext<TEvent> {
  const stack: RequestObservation<TEvent>[] = [];
  return {
    async run<T>(
      observation: RequestObservation<TEvent>,
      work: () => T | Promise<T>,
    ): Promise<T> {
      stack.push(observation);
      try {
        return await work();
      } finally {
        const index = stack.lastIndexOf(observation);
        if (index >= 0) {
          stack.splice(index, 1);
        }
      }
    },
    get(): RequestObservation<TEvent> | undefined {
      return stack.at(-1);
    },
  };
}

function logEvent(logger: ObservationLogger | undefined, event: ObservationEvent): void {
  const context = {
    domain: event.domain,
    requestId: event.requestId,
    actorId: event.actorId,
    subjectId: event.subjectId,
    userId: event.userId,
    outcome: event.outcome,
    metadata: event.metadata,
  };
  switch (event.severity) {
    case "debug":
      logger?.debug?.(event.type, context);
      break;
    case "warn":
      logger?.warn?.(event.type, context);
      break;
    case "error":
      logger?.error?.(event.type, context);
      break;
    default:
      logger?.info?.(event.type, context);
      break;
  }
}

function now(): number {
  return typeof performance !== "undefined" && typeof performance.now === "function"
    ? performance.now()
    : Date.now();
}

function randomId(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  return Math.random().toString(36).slice(2);
}
import { AsyncLocalStorage } from "node:async_hooks";
import type {
  ObservationEvent,
  RequestObservation,
  RequestObservationContext,
} from "./index.js";

export function createAsyncLocalRequestContext<
  TEvent extends ObservationEvent = ObservationEvent,
>(): RequestObservationContext<TEvent> {
  const storage = new AsyncLocalStorage<RequestObservation<TEvent>>();
  return {
    async run<T>(
      observation: RequestObservation<TEvent>,
      work: () => T | Promise<T>,
    ): Promise<T> {
      return await storage.run(observation, work);
    },
    get(): RequestObservation<TEvent> | undefined {
      return storage.getStore();
    },
  };
}
import { describe, expect, it } from "vitest";
import {
  createObservability,
  instrumentMethods,
  readObservationGroup,
} from "./index.js";
import { createAsyncLocalRequestContext } from "./node.js";

describe("superfunction observability", () => {
  it("records async method metrics into the active request", async () => {
    const observability = createObservability({
      service: "test-service",
    });
    const target = {
      async findOne(input: { model: string }) {
        return { id: input.model };
      },
    };
    const observed = instrumentMethods({
      target,
      observability,
      kind: "db",
      component: "test.db",
      extract: ({ property, args }) => ({
        operation: String(property),
        resource: (args[0] as { model?: string }).model,
      }),
    });
    const request = observability.startRequest({
      requestId: "req_test",
      method: "GET",
      path: "/test",
    });

    await observability.runWithRequest(request, () => observed.findOne({ model: "users" }));
    const snapshot = request.finish({ status: 200 });
    const db = readObservationGroup(snapshot, "db");

    expect(snapshot.requestId).toBe("req_test");
    expect(db.count).toBe(1);
    expect(db.errorCount).toBe(0);
    expect(snapshot.metrics[0]?.component).toBe("test.db");
    expect(snapshot.metrics[0]?.resource).toBe("users");
  });

  it("shares active request state across child scopes", async () => {
    const observability = createObservability({
      service: "test-service",
    });
    const child = observability.child({ component: "child" });
    const request = observability.startRequest({
      requestId: "req_child",
      method: "POST",
      path: "/child",
    });

    await observability.runWithRequest(request, async () => {
      child.record({
        kind: "lookup",
        operation: "get",
        durationMs: 2,
        ok: true,
      });
    });

    const snapshot = request.finish({ status: 200 });
    const lookup = readObservationGroup(snapshot, "lookup");

    expect(lookup.count).toBe(1);
    expect(snapshot.metrics[0]?.component).toBe("child");
  });

  it("keeps overlapping async requests isolated with async local context", async () => {
    const observability = createObservability({
      service: "test-service",
      requestContext: createAsyncLocalRequestContext(),
    });
    const firstRequest = observability.startRequest({
      requestId: "req_first",
    });
    const secondRequest = observability.startRequest({
      requestId: "req_second",
    });
    let enterSecondRequest!: () => void;
    let recordFirstMetric!: () => void;
    const secondRequestEntered = new Promise<void>((resolve) => {
      enterSecondRequest = resolve;
    });
    const firstMetricRecorded = new Promise<void>((resolve) => {
      recordFirstMetric = resolve;
    });

    await Promise.all([
      observability.runWithRequest(firstRequest, async () => {
        await secondRequestEntered;
        observability.record({
          kind: "db",
          operation: "first",
          durationMs: 1,
          ok: true,
        });
        recordFirstMetric();
      }),
      observability.runWithRequest(secondRequest, async () => {
        enterSecondRequest();
        await firstMetricRecorded;
        observability.record({
          kind: "cache",
          operation: "second",
          durationMs: 1,
          ok: true,
        });
      }),
    ]);

    const firstSnapshot = firstRequest.finish({ status: 200 });
    const secondSnapshot = secondRequest.finish({ status: 200 });

    expect(readObservationGroup(firstSnapshot, "db").count).toBe(1);
    expect(readObservationGroup(firstSnapshot, "cache").count).toBe(0);
    expect(readObservationGroup(secondSnapshot, "db").count).toBe(0);
    expect(readObservationGroup(secondSnapshot, "cache").count).toBe(1);
  });

  it("routes typed domain events through the events channel", async () => {
    type TestEvent = {
      domain: "test";
      type: "test.started";
      requestId?: string;
      metadata?: { value: number };
    };
    const events: TestEvent[] = [];
    const observability = createObservability<TestEvent>({
      service: "test-service",
      events: {
        emit: (event) => events.push(event),
      },
    });
    const request = observability.startRequest({
      requestId: "req_event",
    });

    await observability.runWithRequest(request, () =>
      request.event({
        domain: "test",
        type: "test.started",
        metadata: { value: 1 },
      })
    );

    expect(events).toEqual([
      {
        domain: "test",
        type: "test.started",
        requestId: "req_event",
        metadata: { value: 1 },
      },
    ]);
  });
});
