export async function registerUserRegion(
  config: Pick<AuthFnConfig, 'database' | 'cacheStore' | 'namespace' | 'observability'>,
  pluginConfig: MultiRegionPluginConfig,
  input: {
    user: Pick<AuthFnUserRecord, 'id' | 'primaryEmail'>;
    runtime: AuthFnRuntimeResolution;
    request?: Request;
  }
): Promise<AuthFnRegionProfileRecord | null> {
  const currentRegion = deriveCurrentRegion(pluginConfig, input.request, input.runtime);
  if (!currentRegion) {
    return null;
  }

  const now = new Date();
  const existing = await findRegionProfileByUserId(config, input.user.id);
  const record: AuthFnRegionProfileRecord = {
    id: existing?.id ?? createIdentifier('region'),
    userId: input.user.id,
    regionId: currentRegion.regionId,
    authority: currentRegion.authority,
    domain: currentRegion.domain ?? null,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now
  };

  let insertedLookup = false;
  if (input.user.primaryEmail) {
    const identifier = normalizeIdentifier(input.user.primaryEmail);
    const cacheKey = createAuthFnCacheKey(config, 'region', identifier);
    const lookupRecord: AuthFnRegionLookupRecord = {
      identifier,
      userId: input.user.id,
      regionId: record.regionId,
      authority: record.authority,
      domain: record.domain ?? undefined,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt
    };

    if (pluginConfig.lookupStore) {
      const result = await pluginConfig.lookupStore.putIfAbsent(lookupRecord);
      insertedLookup = result.inserted;
      if (!result.inserted && result.existing && !recordsReferToSameRegionUser(result.existing, lookupRecord)) {
        const existing = lookupFromRecord(result.existing);
        await setCachedJson(config.cacheStore, {
          key: cacheKey,
          value: {
            found: true,
            lookup: existing
          } satisfies CachedRegionLookup,
          ttlSeconds: AUTHFN_CACHE_TTL_SECONDS.regionHit
        });
        await emitAuthEvent(config, {
          type: 'authfn.region.lookup.conflict',
          requestId: eventRequestId(input.request),
          actorId: input.user.id,
          userId: input.user.id,
          regionId: existing.regionId,
          outcome: 'conflict',
          metadata: {
            identifier,
            attemptedRegionId: record.regionId,
            attemptedAuthority: record.authority,
            authority: existing.authority
          }
        });
        throw new AuthFnRegionMismatchError('Identifier is already registered in another region authority', {
          identifier,
          userId: existing.userId,
          regionId: existing.regionId,
          authority: existing.authority,
          redirectTo: existing.authority,
          continueLocally: false
        });
      }
      if (!result.inserted && result.existing && shouldRefreshExistingLookup(result.existing, lookupRecord)) {
        await pluginConfig.lookupStore.update(lookupRecord);
      }
    }
  }

  try {
    if (existing) {
      await config.database.update<AuthFnRegionProfileRecord>({
        model: 'region_profiles',
        where: [{ field: 'id', operator: 'eq', value: existing.id }],
        data: {
          regionId: record.regionId,
          authority: record.authority,
          domain: record.domain,
          updatedAt: now
        },
        namespace: namespace(config)
      });
    } else {
      await config.database.create<AuthFnRegionProfileRecord>({
        model: 'region_profiles',
        data: record,
        namespace: namespace(config)
      });
    }
  } catch (error) {
    if (insertedLookup && input.user.primaryEmail) {
      const identifier = normalizeIdentifier(input.user.primaryEmail);
      await pluginConfig.lookupStore?.deleteByIdentifier(identifier);
      await config.cacheStore?.delete(createAuthFnCacheKey(config, 'region', identifier));
    }
    throw error;
  }

  if (input.user.primaryEmail) {
    const identifier = normalizeIdentifier(input.user.primaryEmail);
    const cacheKey = createAuthFnCacheKey(config, 'region', identifier);
    const lookupRecord: AuthFnRegionLookupRecord = {
      identifier,
      userId: input.user.id,
      regionId: record.regionId,
      authority: record.authority,
      domain: record.domain ?? undefined,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt
    };
    if (!pluginConfig.lookupStore) {
      await pluginConfig.directory?.registerUser?.({
        userId: input.user.id,
        primaryEmail: input.user.primaryEmail,
        regionId: record.regionId,
        authority: record.authority,
        domain: record.domain ?? undefined,
        request: input.request,
        runtime: input.runtime
      });
    }
    await setCachedJson(config.cacheStore, {
      key: cacheKey,
      value: {
        found: true,
        lookup: lookupFromRecord(lookupRecord)
      } satisfies CachedRegionLookup,
      ttlSeconds: AUTHFN_CACHE_TTL_SECONDS.regionHit
    });
  }

  return record;
}

function recordsReferToSameRegionUser(
  existing: AuthFnRegionLookupRecord,
  expected: AuthFnRegionLookupRecord
): boolean {
  return normalizeIdentifier(existing.identifier) === expected.identifier
    && existing.regionId === expected.regionId
    && (!existing.userId || existing.userId === expected.userId);
}

import {
  DynamoDBClient,
  type DynamoDBClientConfig
} from '@aws-sdk/client-dynamodb';
import {
  DeleteCommand,
  DynamoDBDocumentClient,
  PutCommand,
  QueryCommand,
  UpdateCommand
} from '@aws-sdk/lib-dynamodb';
import type {
  AuthFnRegionLookupRecord,
  AuthFnRegionLookupStore
} from '@authfn/core';

const LOOKUP_RECORD_SORT_KEY = 'LOOKUP';

export interface DynamoDbRegionLookupStoreOptions extends DynamoDBClientConfig {
  tableName: string;
  documentClient?: DynamoDBDocumentClient;
  documentClientConfig?: Parameters<typeof DynamoDBDocumentClient.from>[1];
  consistentRead?: boolean;
}

export class AuthFnDynamoDbLookupStoreError extends Error {
  readonly operation: string;
  readonly retryable: boolean;

  constructor(operation: string, cause: unknown) {
    super(`AuthFn DynamoDB lookup store failed during ${operation}`, {
      cause
    });
    this.name = 'AuthFnDynamoDbLookupStoreError';
    this.operation = operation;
    this.retryable = isRetryableDynamoError(cause);
  }
}

export function createDynamoDbRegionLookupStore(
  options: DynamoDbRegionLookupStoreOptions
): AuthFnRegionLookupStore {
  const client = options.documentClient
    ?? DynamoDBDocumentClient.from(new DynamoDBClient(options), options.documentClientConfig);

  return {
    async getByIdentifier(identifier) {
      try {
        const result = await client.send(new QueryCommand({
          TableName: options.tableName,
          KeyConditionExpression: '#pk = :identifier',
          ExpressionAttributeNames: {
            '#pk': 'PK'
          },
          ExpressionAttributeValues: {
            ':identifier': identifier
          },
          ConsistentRead: options.consistentRead,
          Limit: 1
        }));

        const item = result.Items?.[0];
        return item ? fromItem(item) : null;
      } catch (error) {
        throw new AuthFnDynamoDbLookupStoreError('getByIdentifier', error);
      }
    },

    async putIfAbsent(record) {
      const item = toItem(record);
      try {
        await client.send(new PutCommand({
          TableName: options.tableName,
          Item: item,
          ConditionExpression: 'attribute_not_exists(PK)'
        }));
        return {
          inserted: true
        };
      } catch (error) {
        if (isConditionalCheckFailed(error)) {
          const existing = await this.getByIdentifier(record.identifier);
          return {
            inserted: false,
            existing: existing ?? undefined
          };
        }

        throw new AuthFnDynamoDbLookupStoreError('putIfAbsent', error);
      }
    },

    async update(record) {
      try {
        const result = await client.send(new UpdateCommand({
          TableName: options.tableName,
          Key: {
            PK: record.identifier,
            SK: LOOKUP_RECORD_SORT_KEY
          },
          UpdateExpression: [
            'SET #identifier = :identifier',
            '#userId = :userId',
            '#regionId = :regionId',
            '#authority = :authority',
            '#domain = :domain',
            '#createdAt = if_not_exists(#createdAt, :createdAt)',
            '#updatedAt = :updatedAt'
          ].join(', '),
          ExpressionAttributeNames: {
            '#identifier': 'identifier',
            '#userId': 'userId',
            '#regionId': 'regionId',
            '#authority': 'authority',
            '#domain': 'domain',
            '#createdAt': 'createdAt',
            '#updatedAt': 'updatedAt'
          },
          ExpressionAttributeValues: {
            ':identifier': record.identifier,
            ':userId': record.userId ?? null,
            ':regionId': record.regionId,
            ':authority': record.authority,
            ':domain': record.domain ?? null,
            ':createdAt': serializeDate(record.createdAt),
            ':updatedAt': serializeDate(record.updatedAt)
          },
          ReturnValues: 'ALL_NEW'
        }));

        if (!result.Attributes) {
          throw new Error('DynamoDB update returned no attributes');
        }

        return fromItem(result.Attributes);
      } catch (error) {
        throw new AuthFnDynamoDbLookupStoreError('update', error);
      }
    },

    async deleteByIdentifier(identifier) {
      const existing = await this.getByIdentifier(identifier);
      if (!existing) {
        return;
      }

      try {
        await client.send(new DeleteCommand({
          TableName: options.tableName,
          Key: {
            PK: existing.identifier,
            SK: LOOKUP_RECORD_SORT_KEY
          }
        }));
      } catch (error) {
        throw new AuthFnDynamoDbLookupStoreError('deleteByIdentifier', error);
      }
    }
  };
}

function toItem(record: AuthFnRegionLookupRecord): Record<string, unknown> {
  return {
    PK: record.identifier,
    SK: LOOKUP_RECORD_SORT_KEY,
    identifier: record.identifier,
    userId: record.userId ?? null,
    regionId: record.regionId,
    authority: record.authority,
    domain: record.domain ?? null,
    createdAt: serializeDate(record.createdAt),
    updatedAt: serializeDate(record.updatedAt)
  };
}

function fromItem(item: Record<string, unknown>): AuthFnRegionLookupRecord {
  return {
    identifier: readString(item.identifier ?? item.PK, 'identifier'),
    userId: readOptionalString(item.userId),
    regionId: readString(item.regionId, 'regionId'),
    authority: readString(item.authority, 'authority'),
    domain: readOptionalString(item.domain),
    createdAt: readString(item.createdAt, 'createdAt'),
    updatedAt: readString(item.updatedAt, 'updatedAt')
  };
}

function serializeDate(value: Date | string): string {
  return value instanceof Date ? value.toISOString() : value;
}

function readString(value: unknown, field: string): string {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`DynamoDB lookup record is missing ${field}`);
  }
  return value;
}

function readOptionalString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function isConditionalCheckFailed(error: unknown): boolean {
  return Boolean(
    error
      && typeof error === 'object'
      && (error as { name?: unknown }).name === 'ConditionalCheckFailedException'
  );
}

function isRetryableDynamoError(error: unknown): boolean {
  if (!error || typeof error !== 'object') {
    return false;
  }

  const maybe = error as {
    $retryable?: unknown;
    name?: unknown;
  };
  return Boolean(maybe.$retryable || maybe.name === 'ProvisionedThroughputExceededException');
}
