        }
        opResult = { ok: true };
        break;
      }

      case "unshare": {
        const unshareResult = await executeUnshare(
          db,
          mutation as any,
          resolvedCapabilities,
          namespace,
          actorId,
          logger,
        );
        if (!unshareResult.ok) {
