  side: "from" | "to",
  resource: string | null,
): Record<string, unknown> {
  const endpoint = side === "to" ? relation.to : relation.from;
  if (!endpointIsPolymorphic(endpoint)) return {};
  return { [fkResourceFieldForRelation(relation, side)]: resource };
