  adapter: Adapter,
  resource: string,
  id: string,
  namespace: string,
): Promise<Record<string, unknown> | null> {
  return (await adapter.findOne<Record<string, unknown>>({
    model: resource,
    where: [{ field: "id", operator: "eq", value: id }],
    namespace,
  })) ?? null;
