import { describe, expect, it } from 'vitest';
import { memoryAdapter } from '../../../../packages/db/src/testing/index.js';
import type { AuthFnRuntimeConfig } from '../index.js';
import { createAuthFnRateLimitMiddleware } from '../core/rate-limit.js';

function createConfig(namespace: string): AuthFnRuntimeConfig {
  return {
    database: memoryAdapter({ debug: false }),
    namespace,
    plugins: [],
    rateLimit: {
      enabled: true,
      mode: 'local',
      policies: {
        password: { ipLimit: 1, windowSeconds: 60 },
        'social-start': { ipLimit: 1, windowSeconds: 60 }
      }
    }
  };
}

async function callRateLimitedRoute(
  config: AuthFnRuntimeConfig,
  path: string
): Promise<Response> {
  const middleware = createAuthFnRateLimitMiddleware(config);
  if (!middleware) {
    throw new Error('Expected rate-limit middleware');
  }
  return middleware(
    new Request(`https://account.example.com${path}`, {
      headers: {
        'cf-connecting-ip': '203.0.113.10'
      }
    }),
    {} as never,
    async () => new Response('ok')
  );
}

describe('authfn rate limiting', () => {
  it('keeps counters isolated by route scope', async () => {
    const config = createConfig('rate-limit-scope-test');

    await expect(callRateLimitedRoute(config, '/auth/sign-in/password')).resolves.toHaveProperty('status', 200);
    await expect(callRateLimitedRoute(config, '/auth/social/start')).resolves.toHaveProperty('status', 200);
    await expect(callRateLimitedRoute(config, '/auth/sign-in/password')).rejects.toMatchObject({
      name: 'AuthFnRateLimitedError',
      details: {
        scope: 'password'
      }
    });
    await expect(callRateLimitedRoute(config, '/auth/social/start')).rejects.toMatchObject({
      name: 'AuthFnRateLimitedError',
      details: {
        scope: 'social-start'
      }
    });
  });
});
import { createObservability } from '@superfunctions/observability';
import { describe, expect, it } from 'vitest';

import { createObservabilityMiddleware } from '../observability.js';
import { createRouter } from '../router.js';

describe('request observability middleware', () => {
  it('finalizes the error response when a request handler throws', async () => {
    const completed: Array<{ status: number; snapshotStatus?: number }> = [];
    const observability = createObservability({ service: 'http-test' });
    const router = createRouter({
      routes: [
        {
          method: 'GET',
          path: '/failure',
          handler: () => {
            observability.record({
              kind: 'db',
              operation: 'find',
              durationMs: 2,
              ok: false,
            });
            throw new Error('handler failed');
          },
        },
      ],
      middleware: [
        createObservabilityMiddleware({
          observability,
          onComplete: ({ response, snapshot }) => {
            completed.push({
              status: response.status,
              snapshotStatus: snapshot.status,
            });
          },
        }),
      ],
      onError: () => Response.json({ error: 'handled' }, { status: 503 }),
    });

    const response = await router.handle(new Request('https://example.test/failure'));

    expect(response.status).toBe(503);
    expect(response.headers.get('server-timing')).toContain('db;dur=2');
    expect(response.headers.get('x-superfunctions-db-call-count')).toBe('1');
    expect(completed).toEqual([{ status: 503, snapshotStatus: 503 }]);
  });
});
