export interface SendFnEdgeConfig {
  emailProvider?: EmailProvider;
  whatsappProvider?: WhatsAppProvider;
  email?: {
    /**
     * Full RFC 5322-ish sender string, for example:
     * `Nucleum <no-reply@example.com>`.
