  schema: DatafnSchema,
  e2ee: DatafnE2eeConfig | undefined,
  resource: string,
  record: Record<string, unknown>,
): Promise<Record<string, unknown>> {
  if (!isE2eeEnabled(e2ee) || isE2eePlaintextResource(resource)) {
    return record;
  }

