    provider: 'redis',
    resources: [],
    notes: [
      'Redis and Valkey do not require schema provisioning.',
      'Provision a Redis-compatible endpoint and pass a command client to the adapter.',
      `Key prefix: ${options.prefix ?? '(none)'}`,
    ],
  };
