        engine.docTerms.set(docId, terms);
  ): Promise<void> {
    const terms = engine.docTerms.get(docId);
    if (!terms) return;
    for (const { field, term } of terms) {
      await this.loadTermFromDb(engine, field, term);
      const termMap = engine.postings.get(field)?.get(term);
      if (termMap) {
