export async function encryptMutationPayloadForE2ee(
  schema: DatafnSchema,
  e2ee: DatafnE2eeConfig | undefined,
  payload: unknown,
): Promise<unknown> {
  if (!isE2eeEnabled(e2ee)) return payload;
  if (Array.isArray(payload)) {
    return Promise.all(payload.map((entry) => encryptMutationForE2ee(schema, e2ee, entry)));
  }
  return encryptMutationForE2ee(schema, e2ee, payload);
}

export async function encryptPushPayloadForE2ee(
  schema: DatafnSchema,
  e2ee: DatafnE2eeConfig | undefined,
  payload: unknown,
): Promise<unknown> {
  if (!isE2eeEnabled(e2ee)) return payload;
  if (!isRecordObject(payload) || !Array.isArray(payload.mutations)) return payload;
  return {
    ...payload,
    mutations: await Promise.all(
      payload.mutations.map((entry) => encryptMutationForE2ee(schema, e2ee, entry)),
    ),
  };
}

export async function prepareTransactPayloadForE2ee(
  schema: DatafnSchema,
  e2ee: DatafnE2eeConfig | undefined,
  payload: unknown,
): Promise<unknown> {
  if (!isE2eeEnabled(e2ee) || !isRecordObject(payload) || !Array.isArray(payload.steps)) {
    return payload;
  }

  return {
    ...payload,
    steps: await Promise.all(payload.steps.map(async (step) => {
      if (!isRecordObject(step)) return step;
      if ("query" in step) {
        assertRemoteQueryAllowedForE2ee(e2ee, step.query);
      }
      if (!("mutation" in step)) return step;
      return {
        ...step,
        mutation: await encryptMutationForE2ee(schema, e2ee, step.mutation),
      };
    })),
  };
}

export async function decryptCloneResultForE2ee(
  schema: DatafnSchema,
  e2ee: DatafnE2eeConfig | undefined,
  result: CloneResult,
): Promise<CloneResult> {
  if (!isE2eeEnabled(e2ee) || !result.ok) return result;
  const data: CloneResult["data"] = {};
  for (const [resource, records] of Object.entries(result.data ?? {})) {
    data[resource] = await Promise.all(
      records.map((record) => decryptRecordFields(schema, e2ee, resource, record)),
    );
  }
  return { ...result, data };
}

export async function decryptPullResultForE2ee(
  schema: DatafnSchema,
  e2ee: DatafnE2eeConfig | undefined,
  result: PullResult,
): Promise<PullResult> {
  if (!isE2eeEnabled(e2ee) || !result.ok) return result;
  if ("changes" in result && Array.isArray(result.changes)) {
    return {
      ...result,
      changes: await Promise.all(
        result.changes.map(async (change) => {
          if (!change.record) return change;
          return {
            ...change,
            record: await decryptRecordFields(schema, e2ee, change.resource, change.record),
          };
        }),
    return true;
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return false;
  }
  const record = value as Record<string, unknown>;
  if (record.eq === recordId || record.$eq === recordId) {
    return true;
  }
  const inValue = record.in ?? record.$in;
  return Array.isArray(inValue) &&
    inValue.length === 1 &&
    inValue[0] === recordId;
}

function mergeQueryFilters(existing: unknown, next: Record<string, unknown>): Record<string, unknown> {
  if (!existing || typeof existing !== "object" || Array.isArray(existing)) {
    return next;
  }
  const existingFilters = existing as Record<string, unknown>;
  if (Object.keys(existingFilters).length === 0) {
    return next;
  }
  if (
    Array.isArray(existingFilters.$and) &&
    Object.keys(existingFilters).length === 1
  ) {
    return {
      $and: [...(existingFilters.$and as Record<string, unknown>[]), next],
    };
  }
  return {
    $and: [existingFilters, next],
  };
}

function publicLinkDirectoryRecord(record: DatafnPublicLinkRecord): IndexedDirectoryRecord {
  return {
    key: publicLinkDirectoryKey(record.id),
    value: JSON.stringify(record),
    indexes: {
      "datafn.publicLink.principal": record.principalId,
      "datafn.publicLink.namespace": record.__ns,
      ...(record.resourceRegion ? { "datafn.publicLink.region": record.resourceRegion } : {})
    }
  };
}

function publicLinkDirectoryKey(id: string): string {
  return `datafn:publicLink:${id}`;
}

/**
 * Reads the DataFn public-link credential from a request.
 */
export function readDatafnPublicLinkToken(
  request: Request,
  tokenHeader = "x-datafn-public-link-token"
): string | null {
  const header = request.headers.get(tokenHeader);
  if (header?.trim()) return header.trim();
  const authorization = request.headers.get("authorization")?.trim();
  if (!authorization?.toLowerCase().startsWith("publiclink ")) return null;
  return authorization.slice("publiclink ".length).trim();
}

/**
 * Resolves a DataFn public-link token to its principal and namespace.
 */
export async function resolveDatafnPublicLink(
  database: Adapter,
  token: string | null | undefined,
  options: {
    modelName?: string;
    principalPrefix?: string;
    directory?: IndexedDirectoryStoreAdapter;
  } = {}
): Promise<DatafnPublicLinkPrincipal | null> {
  const parsed = parsePublicLinkToken(token);
  if (!parsed) return null;
  // The database is authoritative for authorization state. A directory entry
  // can remain stale when invalidation fails after a successful revocation.
  const record = await database.findOne<DatafnPublicLinkRecord>({
    model: options.modelName ?? "publicLink",
    where: [{ field: "id", operator: "eq", value: parsed.id }]
  });
  if (!record || record.revokedAt || isExpired(record.expiresAt)) return null;
  if (record.tokenHash !== await hashPublicLinkToken(parsed.token)) return null;
  if (typeof record.__ns !== "string" || record.__ns.length === 0) return null;
