    if (chunks.length === 0) return;
    await this.withTransaction(
      [STORE_NAMES.terms],
      "readwrite",
      async (transaction) => {
        const store = transaction.objectStore(STORE_NAMES.terms);
        await Promise.all(
          chunks.map((chunk) => {
            const record: TermChunkDbRecord = {
              resource,
              field: chunk.key.field,
              term: chunk.key.term,
