export interface AuthFnAdminService {
  listUsers(input: ListUsersInput, context: AdminOperationContext): Promise<UserListResult>;
  getUser(input: UserIdInput, context: AdminOperationContext): Promise<UserResult>;
  deleteUser(input: UserIdInput, context: AdminOperationContext): Promise<DeleteUserResult>;
  listSessions(input: ListSessionsInput, context: AdminOperationContext): Promise<SessionListResult>;
  revokeSession(input: RevokeSessionInput, context: AdminOperationContext): Promise<RevokeSessionResult>;
}

function prepareLegacyConfig(config: LegacyAuthFnConfig): { config: LegacyAuthFnConfig; hooks: Partial<LegacyAuthFnHooks> } {
  const normalized: LegacyAuthFnConfig = { ...config, plugins: config.plugins ?? [] };
  const prepared: LegacyAuthFnConfig = { ...normalized, database: wrapWithSchema(normalized.database, getLegacySchema(normalized)) };
  return { config: prepared, hooks: createLegacyPluginRunner(prepared).hooks };
}
function iso(value: Date | string | null | undefined): string | null { return value == null ? null : new Date(value).toISOString(); }
function userView(user: LegacyAuthFnUserRecord | LegacyAuthFnAdminUserSummary): AuthFnUserAdminView {
  const region = 'regionProfile' in user ? user.regionProfile : undefined;
  return { id: user.id, primaryEmail: user.primaryEmail, emailVerifiedAt: iso(user.emailVerifiedAt), createdAt: iso(user.createdAt)!, updatedAt: iso(user.updatedAt)!, ...(region ? { regionId: region.regionId, authority: region.authority } : {}) };
}
function sessionView(session: LegacyAuthFnSessionRecord, regionId?: string): AuthFnSessionAdminView { return { id: session.id, userId: session.userId, methods: [...session.methods], expiresAt: iso(session.expiresAt)!, revokedAt: iso(session.revokedAt), createdAt: iso(session.createdAt)!, updatedAt: iso(session.updatedAt)!, regionId }; }

export function createAuthFnAdminService(authFnConfig: LegacyAuthFnConfig): AuthFnAdminService {
  const prepared = prepareLegacyConfig(authFnConfig);
  const expectedNamespace = prepared.config.namespace ?? 'authfn';
  const assertNamespace = (context: AdminOperationContext) => { if (context.scope.namespace !== undefined && context.scope.namespace !== expectedNamespace) throw new AdminError('forbidden', 'AuthFn is not bound to the active namespace.'); };
  const scopedUser = async (id: string, context: AdminOperationContext): Promise<LegacyAuthFnUserRecord> => {
    assertNamespace(context);
    const user = await findLegacyUserById(prepared.config, id); if (!user) throw new AdminError('not_found', 'AuthFn user not found.', { details: { id } });
    if (context.scope.region) {
      const profile = await findLegacyRegionProfileByUserId(prepared.config, id);
      if (!profile || profile.regionId !== context.scope.region) throw new AdminError('not_found', 'AuthFn user not found in the active region.', { details: { id } });
    }
    return user;
  };
  return {
    async listUsers(input, context) { assertNamespace(context); const result = await listLegacyAuthFnAdminUsers(prepared.config, { ...input, regionId: context.scope.region }); return { items: result.users.map(userView), nextCursor: result.pageInfo.nextCursor ?? null }; },
    async getUser(input, context) { const user = await scopedUser(input.id, context); const profile = await findLegacyRegionProfileByUserId(prepared.config, user.id); return { item: userView({ ...user, regionProfile: profile ? { regionId: profile.regionId, authority: profile.authority, domain: profile.domain } : undefined } as LegacyAuthFnAdminUserSummary) }; },
    async deleteUser(input, context) { await scopedUser(input.id, context); await deleteLegacyAuthFnAdminUserById(prepared.config, prepared.hooks, { userId: input.id, actorId: context.actor.id }); return { deleted: true, id: input.id }; },
    async listSessions(input, context) { await scopedUser(input.userId, context); const records = await prepared.config.database.findMany<LegacyAuthFnSessionRecord>({ model: 'sessions', where: [{ field: 'userId', operator: 'eq', value: input.userId }], orderBy: [{ field: 'createdAt', direction: 'asc' }, { field: 'id', direction: 'asc' }], namespace: expectedNamespace }); const now = context.now ?? new Date(); return { items: records.filter((record) => !record.revokedAt && record.expiresAt > now).map((record) => sessionView(record, context.scope.region)) }; },
    async revokeSession(input, context) { await scopedUser(input.userId, context); return { item: sessionView(await revokeLegacySessionById(prepared.config, input.id, { userId: input.userId }), context.scope.region) }; }
  };
}

export function createAuthFnAdminAdapter(service: AuthFnAdminService) {
  return createKernelAdminCapabilityAdapter(authFnAdminCapability, {
    'authfn.users.list': ({ input, context }) => service.listUsers(input as ListUsersInput, context),
    'authfn.users.get': ({ input, context }) => service.getUser(input as UserIdInput, context),
    'authfn.users.delete': ({ input, context }) => service.deleteUser(input as UserIdInput, context),
    'authfn.users.list-sessions': ({ input, context }) => service.listSessions(input as ListSessionsInput, context),
    'authfn.sessions.revoke': ({ input, context }) => service.revokeSession(input as RevokeSessionInput, context)
  });
}

export function createAuthFnAdminClient(adminClient: AdminClient) {
  const capability = createCapabilityAdminClient(authFnAdminCapability, adminClient);
  return Object.assign(capability, {
    users: {
      list: (input: ListUsersInput = {}, options?: AdminClientRequestOptions) => capability.invoke('authfn.users.list', input, options),
      get: (input: UserIdInput, options?: AdminClientRequestOptions) => capability.invoke('authfn.users.get', input, options),
      delete: (input: UserIdInput, options?: AdminClientRequestOptions) => capability.invoke('authfn.users.delete', input, options)
    },
    sessions: {
      list: (input: ListSessionsInput, options?: AdminClientRequestOptions) => capability.invoke('authfn.users.list-sessions', input, options),
      revoke: (input: RevokeSessionInput, options?: AdminClientRequestOptions) => capability.invoke('authfn.sessions.revoke', input, options)
    }
  });
}

