function getGlobalFetch(timeoutMs: number): OAuthFetchLike {
  if (!Number.isFinite(timeoutMs) || timeoutMs < 0) {
    throw new OAuthHttpError("OAuth HTTP timeout must be a finite non-negative number", {
      code: "VALIDATION_ERROR",
      status: 400,
      retryable: false
    });
  }
