              code: "INTERNAL_ERROR",
              status: 504,
              retryable: true,
              cause: error
            });
          }
          throw error;
        })
        .finally(clearRequestTimeout);
      return bodyText;
    };

    return {
      ok: response.ok,
      status: response.status,
      headers: {
        get(name: string) {
          return response.headers.get(name);
        }
