export type DatafnE2eeProvider = {
  keyRef: string;
  encrypt(input: {
    resource: string;
    id: string;
    field: string;
    plaintext: Uint8Array;
    aad: Uint8Array;
  }): Promise<DatafnE2eeCipherEnvelope>;
  decrypt(input: {
    resource: string;
    id: string;
    field: string;
    envelope: DatafnE2eeCipherEnvelope;
    aad: Uint8Array;
  }): Promise<Uint8Array>;
