  it("normalizes optional empty relation FK values to null", () => {
    const schema: DatafnSchema = {
      resources: [
        {
          name: "objective",
          version: 1,
          fields: [{ name: "id", type: "string", required: true }],
        },
        {
          name: "task",
          version: 1,
          fields: [
