}

export interface DatafnMultiRegionPluginConfig {
  regionId: string;
  directory: IndexedDirectoryStoreAdapter | DatafnMultiRegionDirectory;
}

export interface DatafnMultiRegionRuntimeConfig {
  regionId: string;
