      resource: mutation.resource,
      records: [{
        ...record,
        __ns: namespace,
        ...(multiRegionRuntime?.regionId ? { __region: multiRegionRuntime.regionId } : {}),
      }],
      operation: op,
    });
  } catch (e) {
    logger?.error("Search index update failed (non-fatal)", {
      error: String(e),
      operation: "search-index-update",
      resource: mutation.resource,
    });
  }
