  it('maps configured bearer token and headers into request headers', async () => {
    const auth = createAuthFnSessionTransportAuth({
      bearerToken: async () => ' session-token ',
      headers: () => ({ 'x-custom-auth-context': 'custom' }),
      plugins: [
