  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }

  return undefined;
}

function ensureOAuthHttpError(error: unknown): OAuthHttpError {
  if (error instanceof OAuthHttpError) {
    return error;
  }

  return new OAuthHttpError(error instanceof Error ? error.message : "OAuth HTTP request failed", {
    code: "INTERNAL_ERROR",
    status: 500,
    retryable: false,
    cause: error
  });
}

/** Creates the shared timeout-aware global fetch adapter used by OAuth transports. */
export function createOAuthFetchLike(
  timeoutMs: number = DEFAULT_OAUTH_REQUEST_TIMEOUT_MS
): OAuthFetchLike {
  if (!Number.isFinite(timeoutMs) || timeoutMs < 0) {
    throw new OAuthHttpError("OAuth HTTP timeout must be a finite non-negative number", {
      code: "VALIDATION_ERROR",
      status: 400,
      retryable: false
    });
  }
  const fetcher = globalThis.fetch;
  if (!fetcher) {
    throw new OAuthHttpError("global fetch is not available", {
      code: "INTERNAL_ERROR",
      status: 500,
      retryable: false
    });
  }

  return async (url, init) => {
    const controller =
      timeoutMs > 0 && typeof AbortController === "function" ? new AbortController() : undefined;
    const timeoutId =
      controller !== undefined ? setTimeout(() => controller.abort(), timeoutMs) : undefined;

    let response: Response;
    try {
      response = await fetcher(url, {
        method: init.method,
        headers: init.headers,
        body: init.body,
        signal: controller?.signal
      });
    } catch (error) {
      if (timeoutId !== undefined) {
        clearTimeout(timeoutId);
      }
      if (controller?.signal.aborted) {
        throw new OAuthHttpError(`OAuth HTTP request timed out after ${timeoutMs}ms`, {
          code: "INTERNAL_ERROR",
          status: 504,
          retryable: true,
          cause: error
        });
      }
      throw error;
    }

    let timeoutCleared = false;
    const clearRequestTimeout = () => {
      if (!timeoutCleared && timeoutId !== undefined) {
        timeoutCleared = true;
        clearTimeout(timeoutId);
      }
    };
    let bodyText: Promise<string> | undefined;
    const readBody = () => {
      bodyText ??= response.text()
        .catch((error) => {
          if (controller?.signal.aborted) {
            throw new OAuthHttpError(`OAuth HTTP request timed out after ${timeoutMs}ms`, {
              code: "INTERNAL_ERROR",
              status: 504,
              retryable: true,
              cause: error
            });
          }
          throw error;
        : undefined
  };
}

function parseJwtPart(value: string): Record<string, unknown> | undefined {
  try {
    const parsed = JSON.parse(new TextDecoder().decode(decodeBase64Url(value)));
    return parsed && typeof parsed === 'object'
      ? parsed as Record<string, unknown>
      : undefined;
  } catch {
    return undefined;
  }
}

function resolveAppleClientSecretTtlSeconds(value: number | undefined) {
  if (Number.isFinite(value) && value !== undefined && value > 0) {
    return Math.min(Math.floor(value), MAX_APPLE_CLIENT_SECRET_TTL_SECONDS);
  }
  return DEFAULT_APPLE_CLIENT_SECRET_TTL_SECONDS;
}

async function importApplePrivateKey(privateKey: string) {
  return globalThis.crypto.subtle.importKey(
    'pkcs8',
    decodePem(privateKey),
    { name: 'ECDSA', namedCurve: 'P-256' },
    false,
    ['sign']
  );
}

function decodePem(pem: string) {
  const normalized = pem
    .replace(/\\n/g, '\n')
    .replace(/-----BEGIN PRIVATE KEY-----/g, '')
    .replace(/-----END PRIVATE KEY-----/g, '')
    .replace(/\s+/g, '');
  return decodeBase64(normalized);
}

function decodeBase64Url(value: string) {
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, '=');
  return decodeBase64(padded);
}

function decodeBase64(value: string) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function base64UrlJson(value: Record<string, unknown>) {
  return base64UrlBytes(new TextEncoder().encode(JSON.stringify(value)));
}

function base64UrlBytes(bytes: Uint8Array) {
  let binary = '';
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function createGlobalOAuthFetchLike(): OAuthFetchLike {
  return async (url, init) => {
    const response = await fetch(url, {
      method: init.method,
      headers: init.headers,
      body: init.body
    });
    return {
      ok: response.ok,
      status: response.status,
      headers: {
        get(name: string) {
          return response.headers.get(name);
        }
      },
      text: () => response.text()
    };
  };
}

