import fs from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

export interface LoadConfigModuleOptions<TValue = unknown> {
  exportNames?: readonly string[];
  exportPriority?: 'default-first' | 'named-first';
  fallbackToModule?: boolean;
  resolveFunctions?: boolean;
  transform?: (
    value: unknown,
    context: LoadedConfigModuleContext
  ) => Promise<TValue> | TValue;
}

export interface LoadedConfigModuleContext {
  path: string;
  module: Record<string, unknown>;
  exportName: string | null;
}

export interface LoadedConfigModule<TValue = unknown>
  extends LoadedConfigModuleContext {
  value: TValue;
}

const SUPPORTED_CONFIG_EXTENSIONS = new Set([
  '.ts',
  '.js',
  '.mjs',
  '.cjs',
  '.json',
]);

export async function loadConfigModule<TValue = unknown>(
  configPath: string,
  options: LoadConfigModuleOptions<TValue> = {}
): Promise<LoadedConfigModule<TValue>> {
  const resolvedPath = path.resolve(configPath);
  const extension = path.extname(resolvedPath).toLowerCase();

  if (!SUPPORTED_CONFIG_EXTENSIONS.has(extension)) {
    throw new Error(
      `Unsupported config module extension: ${extension || '(none)'}`
    );
  }

  await fs.access(resolvedPath);

  const module = await importConfigModule(resolvedPath, extension);
  const selection = selectExport(module, options);
  const value = await transformSelectedValue(
    selection.value,
    {
      path: resolvedPath,
      module,
      exportName: selection.exportName,
    },
    options
  );

  return {
    path: resolvedPath,
    module,
    exportName: selection.exportName,
    value,
  };
}

async function importConfigModule(
  resolvedPath: string,
  extension: string
): Promise<Record<string, unknown>> {
  if (extension === '.json') {
    const raw = await fs.readFile(resolvedPath, 'utf8');
    return { default: JSON.parse(raw) as unknown };
  }

  if (extension === '.ts') {
    const jitiImport = await import('jiti');
    const createJiti = jitiImport.default || jitiImport;
    const loader = createJiti(path.dirname(resolvedPath), {
      interopDefault: false,
      extensions: ['.ts', '.js', '.mjs', '.cjs', '.json'],
    });

    return (await Promise.resolve(
      loader(resolvedPath)
    )) as Record<string, unknown>;
  }

  return (await import(pathToFileURL(resolvedPath).href)) as Record<
    string,
    unknown
  >;
}

function selectExport(
  module: Record<string, unknown>,
  options: LoadConfigModuleOptions<unknown>
): { exportName: string | null; value: unknown } {
  const exportNames = options.exportNames ?? [];
  const exportPriority = options.exportPriority ?? 'default-first';

  const selectNamedExport = (): { exportName: string | null; value: unknown } | null => {
    for (const exportName of exportNames) {
      if (exportName in module) {
        return {
          exportName,
          value: module[exportName],
        };
      }
    }

    return null;
  };

  const selectDefaultExport = (): { exportName: string | null; value: unknown } | null => {
    if ('default' in module) {
      return {
        exportName: 'default',
        value: module.default,
      };
    }

    return null;
  };

  const preferred = exportPriority === 'named-first' ? selectNamedExport() : selectDefaultExport();
  if (preferred) {
      console.error(`   ❌ Error processing ${init.libraryName}:`, e.message);
      console.log(`   Skipping...\n`);
    }
  }

  console.log("✅ Schema generation complete!\n");
  console.log("📝 Next steps:");
  console.log("   1. Import generated schema in your code");
  console.log(
    "   2. Pass schema to ORM constructor (e.g., drizzle(client, { schema }))"
  );
  console.log(
    "   3. Pass ORM instance to adapter (no schema parameter needed)"
  );
}

async function importLibrarySchemaInstances(
  filePath: string
): Promise<Array<{
  libraryName: string;
  packageName: string;
  functionName: string;
  config: any;
  schema: any;
  location: { line: number; column: number };
}>> {
  try {
    const mod = await import(pathToFileURL(filePath).href);
    return Object.values(mod)
      .map(resolveExecutableSchemaSource)
      .filter((source): source is ExecutableSchemaSource => Boolean(source))
      .map((source) => ({
        libraryName: source.metadata.libraryName,
        packageName: source.metadata.packageName,
        functionName: "getSchema",
        config: source.config ?? {},
        schema: source.getSchema(),
        location: { line: 1, column: 1 },
      }));
  } catch {
    return [];
  }
}

interface ExecutableSchemaSource {
  metadata: {
    libraryName: string;
    packageName: string;
  };
  config?: unknown;
  getSchema(): unknown;
}

function resolveExecutableSchemaSource(value: unknown): ExecutableSchemaSource | null {
  if (!value || typeof value !== "object") {
    return null;
  }
  const metadata = (value as Record<PropertyKey, unknown>)[superfunctionsAppMetadata];
  if (!metadata || typeof metadata !== "object") {
    return null;
  }
  const libraryName = (metadata as { libraryName?: unknown }).libraryName;
  const packageName = (metadata as { packageName?: unknown }).packageName;
  if (
    typeof libraryName !== "string" ||
    typeof packageName !== "string" ||
    !("getSchema" in value) ||
    typeof (value as { getSchema?: unknown }).getSchema !== "function"
  ) {
    return null;
  }
  return {
    metadata: { libraryName, packageName },
    config: (value as { config?: unknown }).config,
    getSchema: (value as { getSchema(): unknown }).getSchema.bind(value),
  };
}

export function resolveLibraryPackageEntryPoint(
  packageJson: Record<string, any>
): string {
  const exportRoot = packageJson.exports?.['.'];
  const resolvedExport = resolvePackageExportTarget(exportRoot);

  if (resolvedExport) {
    return resolvedExport;
  }

  if (typeof packageJson.main === 'string' && packageJson.main.length > 0) {
    return packageJson.main;
  }

  return 'index.js';
}

function resolvePackageExportTarget(target: unknown): string | null {
  if (typeof target === 'string' && target.length > 0) {
    return target;
  }

  if (!target || typeof target !== 'object') {
    return null;
  }

  const candidate =
    (target as Record<string, unknown>).import
    ?? (target as Record<string, unknown>).default
    ?? (target as Record<string, unknown>).require;

  return resolvePackageExportTarget(candidate);
}

