  const changeId = getPermissionEntryId(
    mutation.resource,
    namespace,
    resourceId,
    unsharePrincipalId,
  );
  const permissionsTable = getPermissionsTableName();
  const existingPermission = await db.findOne({
    model: permissionsTable,
    where: [{ field: "id", operator: "eq", value: changeId }],
    namespace,
  });

