    scope?: "record" | "resource";
    shareWith?: { principalId?: string; userId?: string };
  },
  resolvedCapabilities: unknown[],
  namespace: string,
  actorId?: string,
  logger?: DatafnLogger,
  multiRegionRuntime?: DatafnMultiRegionRuntimeConfig | null,
): Promise<
  | { ok: true; deleted: boolean; changeId: string }
