describe("SyncEngine push", () => {
  it("pushes contiguous changelog batches with their original client id", async () => {
    vi.useFakeTimers();
    try {
      const storage = new MemoryStorageAdapter(["goal"]);
      await storage.changelogAppend({
        clientId: "client:old",
        mutationId: "mut:old",
        timestampMs: 1,
        mutation: {
          resource: "goal",
          version: 1,
          operation: "insert",
          id: "goal:old",
          record: {
            id: "goal:old",
            type: "INDEFINITE",
            status: "NOT_STARTED",
          },
          clientId: "client:old",
          mutationId: "mut:old",
        },
      });
      await storage.changelogAppend({
        clientId: "client:new",
        mutationId: "mut:new",
        timestampMs: 2,
        mutation: {
          resource: "goal",
          version: 1,
          operation: "insert",
          id: "goal:new",
          record: {
            id: "goal:new",
            type: "INDEFINITE",
            status: "NOT_STARTED",
          },
          clientId: "client:new",
          mutationId: "mut:new",
        },
      });

      const push = vi.fn().mockResolvedValue({
        ok: true,
        result: {
          ok: true,
          applied: ["mut"],
          cursor: "1",
          cursorBefore: "0",
        },
      });
      const remote: any = {
        push,
        pull: vi.fn(),
        clone: vi.fn(),
        query: vi.fn(),
        mutation: vi.fn(),
        transact: vi.fn(),
        seed: vi.fn(),
        reconcile: vi.fn(),
      };

      const engine = new SyncEngine(
        storage,
        remote,
        new EventBus(),
        "client:new",
        schema,
        { pushMaxRetries: 0 },
