/**
 * Test vectors for observability and redaction (OBS-001)
 * 
 * These tests encode the audit gap for correlation ID preservation:
 * - TV-OBS-REDACTION-001: Correlation IDs like requestId are preserved (NOT redacted)
 * - TV-OBS-LOG-001: Logs contain correlation IDs
 * - TV-OBS-LOG-NEG-001: Signed URLs are NOT logged
 */

import { describe, it, expect } from 'vitest';
import { redactSecrets, type LogContext } from '../index.js';

describe('@filefn/server observability redaction', () => {
  describe('TV-OBS-REDACTION-001: Correlation IDs are preserved', () => {
    it('should preserve short requestId values', () => {
      const context: LogContext = {
        requestId: 'req_001',
        uploadSessionId: 'upl_0001',
        fileId: 'file_0001',
        versionId: 'ver_0001',
      };

      const redacted = redactSecrets(context);

      // These should NOT be redacted - this is the audit gap
      // Current implementation redacts these which is wrong
      expect(redacted.requestId).toBe('req_001');
      expect(redacted.uploadSessionId).toBe('upl_0001');
      expect(redacted.fileId).toBe('file_0001');
      expect(redacted.versionId).toBe('ver_0001');
    });

    it('should preserve requestId in log context with other fields', () => {
      const context: LogContext = {
        requestId: 'req_001',
        fileName: 'avatar.png',
        size: 1024,
        mimeType: 'image/png',
      };

      const redacted = redactSecrets(context);

      expect(redacted.requestId).toBe('req_001');
      expect(redacted.fileName).toBe('avatar.png');
      expect(redacted.size).toBe(1024);
      expect(redacted.mimeType).toBe('image/png');
    });

    it('should mark redacted field as false for correlation IDs', () => {
      const context: LogContext = {
        requestId: 'req_001',
      };

      const redacted = redactSecrets(context);

      // The test vector expects this specific shape
      // This verifies correlation IDs are not redacted
      expect(redacted.requestId).toBe('req_001');
      expect(redacted.requestId).not.toBe('[REDACTED]');
    });
  });

  describe('TV-OBS-LOG-001: Logs contain correlation IDs', () => {
    it('should preserve all correlation IDs together', () => {
      const context: LogContext = {
        requestId: 'req_001',
        uploadSessionId: 'upl_0001',
        fileId: 'file_0001',
        versionId: 'ver_0001',
        operation: 'upload.init',
      };

      const redacted = redactSecrets(context);

      // All correlation IDs should be preserved
      expect(redacted.requestId).toBe('req_001');
      expect(redacted.uploadSessionId).toBe('upl_0001');
      expect(redacted.fileId).toBe('file_0001');
      expect(redacted.versionId).toBe('ver_0001');
      expect(redacted.operation).toBe('upload.init');
    });
  });

  describe('TV-OBS-LOG-NEG-001: Signed URLs are NOT logged', () => {
    it('should still redact signed URLs while preserving correlation IDs', () => {
      const context: LogContext = {
        requestId: 'req_001',
        signedUrl: 'https://storage.test/upload/stor_upl_0001/part/1?X-Amz-Signature=secret',
      };

      const redacted = redactSecrets(context);

      // requestId should be preserved
      expect(redacted.requestId).toBe('req_001');
      // signedUrl should be redacted
      expect(redacted.signedUrl).toBe('[REDACTED]');
    });

    it('should redact URLs containing X-Amz-Signature', () => {
      const context: LogContext = {
        requestId: 'req_005',
        url: 'https://s3.amazonaws.com/bucket/key?X-Amz-Signature=abc123',
      };

      const redacted = redactSecrets(context);

      expect(redacted.requestId).toBe('req_005');
      expect(redacted.url).toBe('[REDACTED]');
    });

    it('should redact URLs containing token parameter', () => {
      const context: LogContext = {
        requestId: 'req_006',
        downloadUrl: 'https://storage.example.com/file?token=jwt.token.here',
      };

      const redacted = redactSecrets(context);

      expect(redacted.requestId).toBe('req_006');
      expect(redacted.downloadUrl).toBe('[REDACTED]');
    });
  });

  describe('Upload session token redaction', () => {
    it('should redact upload session token fields while preserving safe IDs', () => {
      const context: LogContext = {
        requestId: 'req_001',
        uploadSessionToken: 'upls_live_0001_secret',
        uploadSessionId: 'upl_0001',
      };

      const redacted = redactSecrets(context);

      expect(redacted.requestId).toBe('req_001');
      expect(redacted.uploadSessionId).toBe('upl_0001');
      expect(redacted.uploadSessionToken).toBe('[REDACTED]');
    });

    it('should recurse into arrays and nested objects for token redaction', () => {
      const context: LogContext = {
        requestId: 'req_001',
        nested: {
          values: ['safe', 'upls_live_abc123'],
        },
      };

      const redacted = redactSecrets(context);

      expect(redacted.requestId).toBe('req_001');
      expect((redacted.nested as any).values).toEqual(['safe', '[REDACTED]']);
    });
  });

  describe('Correlation ID patterns', () => {
    it('should recognize standard correlation ID patterns', () => {
      const patterns = [
        { requestId: 'req_001' },
        { requestId: 'req_010' },
        { requestId: 'req_100' },
        { uploadSessionId: 'upl_0001' },
        { uploadSessionId: 'upl_expired_1' },
        { fileId: 'file_0001' },
        { fileId: 'file_pub_0001' },
        { versionId: 'ver_0001' },
        { versionId: 'ver_other_file' },
      ];

      for (const context of patterns) {
        const redacted = redactSecrets(context as LogContext);
        const key = Object.keys(context)[0];
        const value = Object.values(context)[0];

        // All these should be preserved
        expect(redacted[key]).toBe(value);
      }
    });
  });
});
import { describe, it, expect, vi, beforeEach } from "vitest";
import type { SearchAdapter } from "@searchfn/adapter-contracts";
import { createSearchProvider } from "../src/index";

function makeAdapter(overrides?: Partial<SearchAdapter>): SearchAdapter {
  return {
    name: "mock",
    index: vi.fn().mockResolvedValue(undefined),
    search: vi.fn().mockResolvedValue([]),
    remove: vi.fn().mockResolvedValue(undefined),
    clear: vi.fn().mockResolvedValue(undefined),
    ...overrides,
  };
}

// TV-PROV-004
describe("createSearchProvider — factory creates valid SearchProvider", () => {
  it("returns an object with all required SearchProvider methods", () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter);

    expect(typeof provider.name).toBe("string");
    expect(typeof provider.search).toBe("function");
    expect(typeof provider.updateIndices).toBe("function");
    expect(typeof provider.clearIndices).toBe("function");
    expect(typeof provider.searchAll).toBe("function");
    expect(typeof provider.initialize).toBe("function");
    expect(typeof provider.dispose).toBe("function");
  });

  it("name getter delegates to adapter.name", () => {
    const adapter = makeAdapter({ name: "custom-adapter" });
    const provider = createSearchProvider(adapter);
    expect(provider.name).toBe("custom-adapter");
  });

  it("factory does not modify the adapter instance", () => {
    const adapter = makeAdapter();
    const originalKeys = Object.keys(adapter);
    const originalName = adapter.name;

    createSearchProvider(adapter);

    expect(Object.keys(adapter)).toEqual(originalKeys);
    expect(adapter.name).toBe(originalName);
  });

  it("multiple providers from same adapter are independent", () => {
    const adapter = makeAdapter();
    const p1 = createSearchProvider(adapter, { resourceFields: { tasks: ["title"] } });
    const p2 = createSearchProvider(adapter, { resourceFields: { notes: ["content"] } });
    expect(p1).not.toBe(p2);
  });
});

// TV-PROV-005
describe("createSearchProvider — search delegates to adapter.search", () => {
  let adapter: SearchAdapter;

  beforeEach(() => {
    adapter = makeAdapter({
      search: vi.fn().mockResolvedValue(["doc-1", "doc-2"]),
    });
  });

  it("returns string IDs from adapter.search result", async () => {
    const provider = createSearchProvider(adapter);
    const result = await provider.search({ resource: "tasks", query: "hello" });
    expect(result).toEqual(["doc-1", "doc-2"]);
  });

  it("passes resource and query to adapter.search", async () => {
    const provider = createSearchProvider(adapter);
    await provider.search({ resource: "notes", query: "report" });
    expect(adapter.search).toHaveBeenCalledWith(
      expect.objectContaining({ resource: "notes", query: "report" }),
    );
  });

  it("defaults limit to 50 when not provided", async () => {
    const provider = createSearchProvider(adapter);
    await provider.search({ resource: "tasks", query: "x" });
    expect(adapter.search).toHaveBeenCalledWith(
      expect.objectContaining({ limit: 50 }),
    );
  });

  it("uses provided limit when specified", async () => {
    const provider = createSearchProvider(adapter);
    await provider.search({ resource: "tasks", query: "x", limit: 10 });
    expect(adapter.search).toHaveBeenCalledWith(
      expect.objectContaining({ limit: 10 }),
    );
  });

  it("converts numeric DocId results to strings", async () => {
    (adapter.search as ReturnType<typeof vi.fn>).mockResolvedValue([1, 2, 3]);
    const provider = createSearchProvider(adapter);
    const result = await provider.search({ resource: "tasks", query: "x" });
    expect(result).toEqual(["1", "2", "3"]);
  });

  it("forwards AbortSignal to adapter.search", async () => {
    const provider = createSearchProvider(adapter);
    const controller = new AbortController();
    await provider.search({
      resource: "tasks",
      query: "x",
      signal: controller.signal,
    });
    expect(adapter.search).toHaveBeenCalledWith(
      expect.objectContaining({ signal: controller.signal }),
    );
  });
});

describe("createSearchProvider — updateIndices", () => {
  it("clears a resource through the adapter before a full rebuild", async () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter);

    await provider.clearIndices?.("tasks");

    expect(adapter.clear).toHaveBeenCalledWith("tasks");
  });

  it("calls adapter.remove on delete operation", async () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter);
    await provider.updateIndices({
      resource: "tasks",
      records: [{ id: "1" }, { id: "2" }],
      operation: "delete",
    });
    expect(adapter.remove).toHaveBeenCalledWith({ resource: "tasks", ids: ["1", "2"] });
    expect(adapter.index).not.toHaveBeenCalled();
  });

  it("stringifies delete ids before delegating to adapter.remove", async () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter);
    await provider.updateIndices({
      resource: "tasks",
      records: [{ id: 1 }, { id: 2 }],
      operation: "delete",
    });
    expect(adapter.remove).toHaveBeenCalledWith({ resource: "tasks", ids: ["1", "2"] });
  });

  it("calls adapter.index on upsert operation", async () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter, {
      resourceFields: { tasks: ["title"] },
    });
    await provider.updateIndices({
      resource: "tasks",
      records: [{ id: "1", title: "Hello" }],
      operation: "upsert",
    });
    expect(adapter.index).toHaveBeenCalledWith({
      resource: "tasks",
      documents: [{ id: "1", fields: { title: "Hello" }, metadata: {} }],
    });
  });

  it("converts non-string field values to strings", async () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter);
    await provider.updateIndices({
      resource: "tasks",
      records: [{ id: "1", count: 42, active: true, meta: { x: 1 } }],
      operation: "upsert",
    });
    expect(adapter.index).toHaveBeenCalledWith(
      expect.objectContaining({
        documents: [
          {
            id: "1",
            fields: { count: "42", active: "true", meta: '{"x":1}' },
            metadata: {},
          },
        ],
      }),
    );
  });

  it("uses configured resourceFields when extracting indexed fields", async () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter, {
      resourceFields: { tasks: ["title"] },
    });

    await provider.updateIndices({
      resource: "tasks",
      records: [{ id: "1", title: "Hello", body: "Ignored" }],
      operation: "upsert",
    });

    expect(adapter.index).toHaveBeenCalledWith({
      resource: "tasks",
      documents: [{ id: "1", fields: { title: "Hello" }, metadata: {} }],
    });
  });

  it("falls back to String(value) when JSON serialization fails", async () => {
    const adapter = makeAdapter();
    const provider = createSearchProvider(adapter);
    const circular: Record<string, unknown> = {};
    circular.self = circular;

    await provider.updateIndices({
      resource: "tasks",
      records: [{ id: "1", meta: circular }],
      operation: "upsert",
    });

    expect(adapter.index).toHaveBeenCalledWith(
      expect.objectContaining({
        documents: [{ id: "1", fields: { meta: "[object Object]" }, metadata: {} }],
      }),
    );
  });
});

