    const client = createDatafnClient({
      schema,
      sync: { mode: "sync", remoteAdapter: remote },
      clientId: "test-destroy",
    });

    await client.destroy();

    await expect(client.search({ query: "test" })).rejects.toMatchObject({
      code: "DFQL_INVALID",
    });
  });
});

