import type { DatafnRelationSchema, DatafnSchema } from "./types.js";
import { endpointIncludes, endpointList, firstEndpoint } from "./relation-endpoints.js";

export type DatafnRelationFkField = {
  field: string;
  resourceField?: string;
  optional: boolean;
};

function htreeFkField(relation: DatafnRelationSchema): string {
  return relation.fkField || relation.inverse || "parentId";
}

function fkFieldForOneMany(relation: DatafnRelationSchema): string {
  return relation.fkField || relation.inverse || `${firstEndpoint(relation.from)}Id`;
}

function fkFieldForManyOne(relation: DatafnRelationSchema): string {
  return relation.fkField || `${relation.relation ?? firstEndpoint(relation.to)}Id`;
}

function fkResourceFieldForRelation(
  relation: DatafnRelationSchema,
  side: "from" | "to",
): string {
  if (relation.fkResourceField) return relation.fkResourceField;
  if (relation.type === "htree") {
    return `${htreeFkField(relation).replace(/Id$/, "")}Resource`;
  }
  const base = side === "to"
    ? (relation.relation || "target")
    : (relation.inverse || relation.relation || "source");
  return `${base.replace(/Id$/, "")}Resource`;
}

function isOptionalResourceField(
  schema: DatafnSchema,
  resourceName: string,
  fieldName: string,
): boolean {
  const resource = schema.resources.find((candidate) => candidate.name === resourceName);
  const field = resource?.fields.find((candidate) => candidate.name === fieldName);
  if (!field) return true;
  return field.required !== true && field.nullable === true;
}

/**
 * Returns generated or declared relation FK fields that live on a resource table.
 */
export function getRelationFkFieldsForResource(
  schema: DatafnSchema,
  resourceName: string,
): DatafnRelationFkField[] {
  const fields = new Map<string, DatafnRelationFkField>();
  const add = (field: string, resourceField?: string) => {
    if (fields.has(field)) return;
    fields.set(field, {
      field,
      resourceField,
      optional: isOptionalResourceField(schema, resourceName, field),
    });
  };

  for (const relation of schema.relations ?? []) {
    if (relation.type === "many-one" && endpointIncludes(relation.from, resourceName)) {
      const toResources = endpointList(relation.to);
      add(
        fkFieldForManyOne(relation),
        toResources.length > 1 ? fkResourceFieldForRelation(relation, "to") : undefined,
      );
    } else if (relation.type === "one-many" && endpointIncludes(relation.to, resourceName)) {
      const fromResources = endpointList(relation.from);
      add(
        fkFieldForOneMany(relation),
        fromResources.length > 1 ? fkResourceFieldForRelation(relation, "from") : undefined,
      );
    } else if (relation.type === "htree" && endpointIncludes(relation.to, resourceName)) {
      const fromResources = endpointList(relation.from);
      add(
        htreeFkField(relation),
        fromResources.length > 1 ? fkResourceFieldForRelation(relation, "from") : undefined,
      );
    }
  }

  return [...fields.values()];
}

/**
 * Converts empty-string optional relation FK values to null before persistence.
 */
export function normalizeRelationFkRecord(
  schema: DatafnSchema,
  resourceName: string,
  record: Record<string, unknown>,
): Record<string, unknown> {
  const next = { ...record };
  for (const field of getRelationFkFieldsForResource(schema, resourceName)) {
    if (!field.optional) continue;
    if (!(field.field in next)) continue;
    const value = next[field.field];
    if (value !== "") continue;
    next[field.field] = null;
    if (field.resourceField && field.resourceField in next) {
      next[field.resourceField] = null;
    }
  }
  return next;
}
import type { DatafnRelationSchema, DatafnSchema } from "./types.js";

export type DatafnRelationEndpoint = string | readonly string[];

export type DatafnRelationDirection = "forward" | "inverse";

export type DatafnRelationMatch = {
  relation: DatafnRelationSchema;
  direction: DatafnRelationDirection;
};

type DatafnEndpointSchema = {
  resources: readonly { name: string; idPrefix?: string }[];
};

export function endpointList(endpoint: DatafnRelationEndpoint): string[] {
  return typeof endpoint === "string" ? [endpoint] : [...endpoint];
}

export function endpointIncludes(
  endpoint: DatafnRelationEndpoint,
  resource: string,
): boolean {
  return endpointList(endpoint).includes(resource);
}

export function firstEndpoint(endpoint: DatafnRelationEndpoint): string {
  return endpointList(endpoint)[0] ?? "";
}

export function resourceNameFromId(id: unknown): string | undefined {
  if (typeof id !== "string") return undefined;
  const index = id.indexOf(":");
  if (index <= 0) return undefined;
  return id.slice(0, index);
}

export function resolveEndpointResource(
  endpoint: DatafnRelationEndpoint,
  id: unknown,
  schema?: DatafnEndpointSchema,
): string | undefined {
  const resources = endpointList(endpoint);
  if (resources.length === 1) return resources[0];
  if (typeof id === "string" && schema) {
    const prefixedMatch = schema.resources
      .filter((resource) => resources.includes(resource.name))
      .map((resource) => ({
        name: resource.name,
        prefix: resource.idPrefix ?? `${resource.name}:`,
      }))
      .filter((candidate) => id.startsWith(candidate.prefix))
      .sort((left, right) => right.prefix.length - left.prefix.length)[0];
    if (prefixedMatch) {
      return prefixedMatch.name;
    }
  }
  const resourceFromId = resourceNameFromId(id);
  if (resourceFromId && resources.includes(resourceFromId)) {
    return resourceFromId;
  }
  return undefined;
}

export function relationMatchesForward(
  relation: DatafnRelationSchema,
  resource: string,
  relationName: string,
): boolean {
  return (
    endpointIncludes(relation.from, resource) &&
    relation.relation === relationName
  );
}

export function relationMatchesInverse(
  relation: DatafnRelationSchema,
  resource: string,
  relationName: string,
): boolean {
  return (
    endpointIncludes(relation.to, resource) &&
    relation.inverse === relationName
  );
}

export function findRelationMatch(
  schema: DatafnSchema,
  resource: string,
  relationName: string,
): DatafnRelationMatch | undefined {
  return schema.relations
    ?.map((relation) => {
      if (relationMatchesForward(relation, resource, relationName)) {
        return { relation, direction: "forward" as const };
      }
      if (relationMatchesInverse(relation, resource, relationName)) {
        return { relation, direction: "inverse" as const };
      }
      return undefined;
    })
    .find((match): match is DatafnRelationMatch => Boolean(match));
}

export function relationSourceEndpoint(
  relation: DatafnRelationSchema,
  direction: DatafnRelationDirection,
): DatafnRelationEndpoint {
  return direction === "forward" ? relation.from : relation.to;
}

export function relationTargetEndpoint(
  relation: DatafnRelationSchema,
  direction: DatafnRelationDirection,
): DatafnRelationEndpoint {
  return direction === "forward" ? relation.to : relation.from;
}

export function relationKeyFor(
  fromResource: string,
  relation: DatafnRelationSchema,
): string {
  return `${fromResource}.${relation.relation}`;
}
