async function callRateLimitedRoute(
  config: AuthFnRuntimeConfig,
  path: string,
  headers: Record<string, string> = { 'cf-connecting-ip': '203.0.113.10' }
): Promise<Response> {
  const middleware = createAuthFnRateLimitMiddleware(config);
