import type {
  ObservabilityInput,
  RequestObservationSnapshot,
  SuperfunctionObservability,
} from "@superfunctions/observability";
import {
  normalizeObservability,
  readObservationGroup,
  roundObservationMs,
} from "@superfunctions/observability";
import type { Middleware } from "./types.js";

export interface ServerTimingOptions {
  totalName?: string;
  groups?: Record<string, string>;
}

export interface ObservationHeaderOptions {
  prefix?: string;
  exposeCounts?: boolean;
  exposeDurations?: boolean;
  groups?: string[];
}

export interface RequestObservabilityMiddlewareOptions<TContext = any> {
  observability?: ObservabilityInput;
  serverTiming?: boolean | ServerTimingOptions;
  headers?: false | ObservationHeaderOptions;
  labels?: Record<string, string>;
  onComplete?: (input: {
    request: Request;
    response: Response;
    context: TContext;
    snapshot: RequestObservationSnapshot;
  }) => void | Promise<void>;
}

export interface RunObservedRequestOptions {
  observability?: ObservabilityInput;
  request: Request;
  labels?: Record<string, string>;
  status?: number | (() => number | undefined);
  responseHeaders?: Headers | (() => Headers | undefined);
  serverTiming?: boolean | ServerTimingOptions;
  headers?: false | ObservationHeaderOptions;
  finishExisting?: boolean;
  work: () => void | Promise<void>;
  onComplete?: (input: {
    request: Request;
    snapshot: RequestObservationSnapshot;
  }) => void | Promise<void>;
}

export async function runObservedRequest(
  options: RunObservedRequestOptions,
): Promise<RequestObservationSnapshot | undefined> {
  const observability = normalizeObservability(options.observability);
  if (!observability) {
    await options.work();
    return undefined;
  }

  const existing = observability.getCurrentRequest();
  const observation = existing ?? observability.startRequest({
    request: options.request,
    labels: options.labels,
  });

  if (existing) {
    await options.work();
  } else {
    await observability.runWithRequest(observation, options.work);
  }

  const status = typeof options.status === "function" ? options.status() : options.status;
  const snapshot = existing && !options.finishExisting
    ? observation.snapshot({ status, labels: options.labels })
    : observation.finish({ status, labels: options.labels });

  const responseHeaders = typeof options.responseHeaders === "function"
    ? options.responseHeaders()
    : options.responseHeaders;
  if (responseHeaders) {
    applyObservationHeaders(responseHeaders, snapshot, {
      serverTiming: options.serverTiming,
      headers: options.headers,
    });
  }

  await options.onComplete?.({
    request: options.request,
    snapshot,
  });

  return snapshot;
}

export function createObservabilityMiddleware<TContext = any>(
  options: RequestObservabilityMiddlewareOptions<TContext>,
): Middleware<TContext> {
  const observability = normalizeObservability(options.observability);

  return async (request, context, next) => {
    if (!observability) {
      return next();
    }

    const existing = observability.getCurrentRequest();
    if (existing) {
      return next();
    }

    const observation = observability.startRequest({
      request,
      labels: options.labels,
    });

    let response = await observability.runWithRequest(observation, next);
    const snapshot = observation.finish({
      status: response.status,
    });
    const headers = new Headers(response.headers);
    applyObservationHeaders(headers, snapshot, {
      serverTiming: options.serverTiming,
      headers: options.headers,
    });
    response = new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });

    await options.onComplete?.({
      request,
      response,
      context,
      snapshot,
    });

    return response;
  };
}

export function applyObservationHeaders(
  headers: Headers,
  snapshot: RequestObservationSnapshot,
  options: {
    serverTiming?: boolean | ServerTimingOptions;
    headers?: false | ObservationHeaderOptions;
  } = {},
): void {
  if (options.serverTiming !== false) {
    headers.set(
      "server-timing",
      formatServerTiming(
        snapshot,
        typeof options.serverTiming === "object" ? options.serverTiming : undefined,
      ),
    );
  }

  if (options.headers !== false) {
    applyMetricHeaders(headers, snapshot, options.headers);
  }
}

export function formatServerTiming(
  snapshot: RequestObservationSnapshot,
  options: ServerTimingOptions = {},
): string {
  const totalName = options.totalName ?? "app";
  const groupNames = options.groups ?? {};
  const entries = [`${totalName};dur=${roundObservationMs(snapshot.totalDurationMs)}`];
  const kinds = Array.from(new Set([
    ...Object.keys(snapshot.groups),
    ...Object.keys(groupNames),
  ]));

  for (const kind of kinds) {
    const group = readObservationGroup(snapshot, kind);
    const name = groupNames[kind] ?? kind;
    entries.push(`${name};dur=${roundObservationMs(group.durationMs)}`);
    entries.push(`${name}max;dur=${roundObservationMs(group.maxDurationMs)}`);
    entries.push(`${name}count;desc="${group.count}"`);
  }

  return entries.join(", ");
}

export function applyMetricHeaders(
  headers: Headers,
  snapshot: RequestObservationSnapshot,
  options: ObservationHeaderOptions = {},
): void {
  const prefix = options.prefix ?? "x-superfunctions";
  const exposeCounts = options.exposeCounts ?? true;
  const exposeDurations = options.exposeDurations ?? true;
  const kinds = Array.from(new Set([
    ...Object.keys(snapshot.groups),
    ...(options.groups ?? []),
  ]));

  for (const kind of kinds) {
    const group = readObservationGroup(snapshot, kind);
    if (exposeCounts) {
      headers.set(`${prefix}-${kind}-call-count`, String(group.count));
    }
    if (exposeDurations) {
      headers.set(`${prefix}-${kind}-duration-ms`, String(roundObservationMs(group.durationMs)));
      headers.set(`${prefix}-${kind}-max-duration-ms`, String(roundObservationMs(group.maxDurationMs)));
    }
  }
}

export function resolveObservability(
  input: ObservabilityInput,
): SuperfunctionObservability | undefined {
  return normalizeObservability(input);
}
import type { DatafnRemoteAdapter } from "./client.js";
import { createClientError } from "./errors.js";
import { createDatafnPublicLinkAuthPlugin } from "./auth.js";
import { isDatafnErrorCode } from "@datafn/core";

type DatafnPublicLinksRemoteAdapter = DatafnRemoteAdapter & {
  publicLinks?(endpoint: string, payload: unknown): Promise<unknown>;
};

export type DatafnPublicLinkShareLevel = "viewer" | "editor" | "owner";
export type DatafnPublicLinkShareScope = "record" | "resource";

export interface CreateDatafnPublicLinkInput {
  resource: string;
  recordId?: string | null;
  scope: DatafnPublicLinkShareScope;
  level: DatafnPublicLinkShareLevel;
  expiresAt?: number | string | null;
}

export interface DatafnPublicLinkGrant {
  id: string;
  token: string;
  principalId: string;
  resource: string;
  recordId: string | null;
  scope: DatafnPublicLinkShareScope;
  level: DatafnPublicLinkShareLevel;
}

export interface DatafnResolvedPublicLink {
  principalId: string;
  resource: string;
  recordId: string | null;
  scope: DatafnPublicLinkShareScope;
  level: DatafnPublicLinkShareLevel;
}

export interface DatafnPublicLinksApi {
  create(input: CreateDatafnPublicLinkInput): Promise<DatafnPublicLinkGrant>;
  revoke(input: { id: string }): Promise<void>;
  resolve(input: { token: string }): Promise<DatafnResolvedPublicLink>;
  principalId(linkId: string): string;
  authPlugin: typeof createDatafnPublicLinkAuthPlugin;
}

/**
 * Creates the DataFn public-link client API backed by the configured remote adapter.
 */
export function createDatafnPublicLinksApi(
  remote: DatafnPublicLinksRemoteAdapter
): DatafnPublicLinksApi {
  return {
    async create(input) {
      const result = await postPublicLink(remote, "public-links", input);
      return result as DatafnPublicLinkGrant;
    },
    async revoke(input) {
      await postPublicLink(remote, "public-links/revoke", input);
    },
    async resolve(input) {
      const result = await postPublicLink(remote, "public-links/resolve", input);
      return result as DatafnResolvedPublicLink;
    },
    principalId(linkId) {
      const normalized = linkId.trim();
      if (!normalized) {
        throw createClientError("DFQL_INVALID", "Public link id is required", {
          path: "id"
        });
      }
      return `public_link:${normalized}`;
    },
    authPlugin: createDatafnPublicLinkAuthPlugin
  };
}

async function postPublicLink(
  remote: DatafnPublicLinksRemoteAdapter,
  endpoint: string,
  payload: unknown
): Promise<unknown> {
  if (!remote.publicLinks) {
    throw createClientError(
      "TRANSPORT_ERROR",
      "DataFn remote adapter does not support public links",
      { path: "sync.remoteAdapter.publicLinks" }
    );
  }
  const response = await remote.publicLinks(endpoint, payload);
  if (response && typeof response === "object") {
    const envelope = response as {
      ok?: boolean;
      result?: unknown;
      error?: { code?: string; message?: string; details?: unknown };
    };
    if (envelope.ok === true) return envelope.result;
    if (envelope.ok === false) {
      throw createClientError(
        isDatafnErrorCode(envelope.error?.code)
          ? envelope.error.code
          : "DFQL_INVALID",
        envelope.error?.message ?? "DataFn public link request failed",
        normalizeErrorDetails(envelope.error?.details)
      );
    }
  }
  return response;
}

function normalizeErrorDetails(details: unknown): { path: string; [key: string]: unknown } {
  if (details && typeof details === "object" && !Array.isArray(details)) {
    const record = details as Record<string, unknown>;
    return {
      ...record,
      path: typeof record.path === "string" ? record.path : "$"
    };
  }
  return { path: "$" };
}
import { instrumentKVStore, type Adapter, type AtomicKVStoreAdapter, type KVStoreAdapter } from '@superfunctions/db';
import { normalizeObservability, type ObservabilityInput } from '@superfunctions/observability';

export { KVStoreAdapter };

export type LegacyWindowAlgorithm = 'sliding-window'|'fixed-window';
export type RateLimitAlgorithm = LegacyWindowAlgorithm | 'token-bucket';

export interface RateLimitConfig {
  windowMs: number;
  maxRequests: number;
  keyPrefix?: string;
  persistence?: Adapter | KVStoreAdapter;
  atomicStore?: AtomicKVStoreAdapter;
  algorithm?: RateLimitAlgorithm;
  now?: () => number;
  observability?: ObservabilityInput;
  component?: string;
}

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetAt: string; // ISO8601
  total: number;
}

export interface CheckLimitInput {
  key: string;
  windowSeconds?: number;
  limit?: number;
}

export interface CheckManyLimitsInput {
  keys: string[];
  windowSeconds?: number;
  limit?: number;
}

export interface RateLimitManyResult {
  allowed: boolean;
  remainingByKey: Map<string, number>;
  resetAtByKey: Map<string, string>;
  resetAt: string;
  total: number;
}

export interface RateLimiter {
  check(input: CheckLimitInput): Promise<RateLimitResult>;
  checkMany(input: CheckManyLimitsInput): Promise<RateLimitManyResult>;
  reset(key: string): Promise<void>;
}

interface KVSetInput {
  key: string;
  value: string;
  ttlSeconds?: number;
}

interface FixedWindowState {
  count: number;
  windowStart: number;
  expiresAt?: number;
}

interface SlidingWindowState {
  timestamps: number[];
  expiresAt?: number;
}

interface TokenBucketState {
  tokens: number;
  lastRefill: number;
  expiresAt?: number;
}

function createInMemoryKVStore(now: () => number = Date.now): KVStoreAdapter {
  const store = new Map<string, { value: string; expiresAt?: number }>();

  return {
    async get(key: string): Promise<string | null> {
      const entry = store.get(key);
      if (!entry) return null;
      if (entry.expiresAt && now() > entry.expiresAt) {
        store.delete(key);
        return null;
      }
      return entry.value;
    },
    async set(input: { key: string; value: string; ttlSeconds?: number }): Promise<void> {
      store.set(input.key, {
        value: input.value,
        expiresAt: input.ttlSeconds ? now() + input.ttlSeconds * 1000 : undefined,
      });
    },
    async delete(key: string): Promise<void> {
      store.delete(key);
    },
  };
}

function isAdapter(p: unknown): p is Adapter {
  return !!p && typeof p === 'object' && 'findOne' in p && 'create' in p;
}

function ensureKV(p: Adapter | KVStoreAdapter, now: () => number): KVStoreAdapter {
  if (isAdapter(p)) {
    return {
      async get(key: string) {
        const res = await p.findOne<{ value: string; expiresAt?: string }>({
          model: 'rate_limits',
          where: [{ field: 'key', operator: 'eq', value: key }],
        });
        if (!res) return null;
        if (res.expiresAt && new Date(res.expiresAt).getTime() < now()) {
          await p.delete({ model: 'rate_limits', where: [{ field: 'key', operator: 'eq', value: key }] });
          return null;
        }
        return res.value;
      },
      async set(input: KVSetInput) {
        const expiresAt = input.ttlSeconds
          ? new Date(now() + input.ttlSeconds * 1000).toISOString()
          : undefined;
        await p.upsert({
          model: 'rate_limits',
          where: [{ field: 'key', operator: 'eq', value: input.key }],
          create: { key: input.key, value: input.value, expiresAt },
          update: { value: input.value, expiresAt },
        });
      },
      async delete(key: string) {
        await p.delete({ model: 'rate_limits', where: [{ field: 'key', operator: 'eq', value: key }] });
      },
    };
  }
  return p;
}

function parseState<T>(data: string | null): T | null {
  if (!data) return null;
  try {
    return JSON.parse(data) as T;
  } catch {
    return null;
  }
}

export function createRateLimiter(config: RateLimitConfig): RateLimiter {
  const now = config.now ?? Date.now;
  const {
    windowMs,
    maxRequests,
    keyPrefix = 'ratelimit:',
    persistence = createInMemoryKVStore(now),
    atomicStore,
    algorithm = 'fixed-window',
    observability: observabilityInput,
    component = 'rate-limit',
  } = config;

  const observability = normalizeObservability(observabilityInput)?.child({ component });
  if (atomicStore && typeof atomicStore.compareAndSet !== 'function') {
    throw new Error('RATE_LIMIT_ATOMIC_CAS_REQUIRED');
  }
  const atomic = atomicStore
    ? instrumentKVStore(atomicStore, {
        observability,
        kind: 'cache',
        component: `${component}.atomic`,
      })
    : undefined;
  const kv = instrumentKVStore(ensureKV(persistence, now), {
    observability,
    kind: 'cache',
    component: `${component}.cache`,
  });
  const keyLocks = new Map<string, Promise<void>>();

  async function withKeyLock<T>(key: string, work: () => Promise<T>): Promise<T> {
    const prior = keyLocks.get(key) ?? Promise.resolve();
    let resolveLock!: () => void;
    const current = new Promise<void>((resolve) => {
      resolveLock = resolve;
    });
    const queued = prior.then(() => current);
    keyLocks.set(key, queued);

    await prior;
    try {
      return await work();
    } finally {
      resolveLock();
      if (keyLocks.get(key) === queued) {
        keyLocks.delete(key);
      }
    }
  }

  async function withKeyLocks<T>(keys: string[], work: () => Promise<T>): Promise<T> {
    const uniqueKeys = [...new Set(keys)].sort();
    const releases: Array<() => void> = [];
    const queuedLocks: Array<{ key: string; queued: Promise<void> }> = [];

    try {
