  /** Deletes the shared IndexedDB database. */
  async deleteDatabase(): Promise<void> {
    await this.close();
    const factory = getIndexedDbFactory();
    await new Promise<void>((resolve, reject) => {
      const request = factory.deleteDatabase(this.dbName);
