          ),
          this.requestToPromise<number>(
            transaction.objectStore(STORE_NAMES.cacheState).index(RESOURCE_INDEX).count(resource),
          ),
        ]);
        return termCount > 0 || cacheCount > 0;
      },
    );
  }

