    expect(sorted[1].id).toBe("2");
    expect(sorted[2].id).toBe("3");
  });

  it("does not mutate original array", () => {
    const original = [...records];
    sortRecords(records, parseSortTerms(["name:desc"]));
    expect(records).toEqual(original);
  });
});
