function generateDropTableSQL(tableName: string, ifExists: boolean = true): string {
  const ifExistsClause = ifExists ? 'IF EXISTS ' : '';
  return `-- DROP TABLE ${ifExistsClause}${tableName}; -- Commented out for safety`;
}

