/**
 * Execute a single mutation
 */
export async function executeMutation(
  mutation: DFQLMutation,
  schema: DatafnSchema,
  db: Adapter,
  idempotencyStore: IdempotencyStore,
  changeTracking: ChangeTrackingService,
  plugins: DatafnPlugin[] = [],
  namespace: string,
  actorId?: string,
  logger?: DatafnLogger,
  searchProvider?: SearchProvider,
  insideTransaction = false,
  deferPermissionDirectorySync?: (
    sync: (committedDb: Adapter) => Promise<void>,
  ) => void,
): Promise<MutationResult> {
  const multiRegionRuntime = getDatafnMultiRegionRuntimeConfig(plugins);
  const syncPermissionDirectoryAfterCommit = async (committedDb = db) => {
    try {
      await syncDatafnPermissionGrantAfterCommit(
        committedDb,
        mutation,
        namespace,
        multiRegionRuntime,
      );
    } catch (error) {
      logger?.error("Permission directory reconciliation failed after commit", {
        error: String(error),
        operation: mutation.operation,
        resource: mutation.resource,
      });
    }
  };
  const reconcilePermissionDirectoryAfterCommit = async () => {
    if (insideTransaction && deferPermissionDirectorySync) {
      deferPermissionDirectorySync(syncPermissionDirectoryAfterCommit);
      return;
    }
    await syncPermissionDirectoryAfterCommit();
  };
  // clientId and mutationId are optional. When absent, skip idempotency tracking.
  // EXE-009: Use crypto.randomUUID() for unpredictable anonymous mutation IDs
  const effectiveMutationId = mutation.mutationId || randomUUID();

  // Check idempotency only when both IDs are provided
  if (mutation.clientId && mutation.mutationId) {
    const cached = await idempotencyStore.get(
      mutation.clientId,
      mutation.mutationId,
    );
    if (cached && !isRetryableMutationResult(cached)) {
      return { ...cached, deduped: true };
    }
    unsharePrincipalId,
  );
  const permissionsTable = getPermissionsTableName();
  const existingPermission = await db.findOne({
    model: permissionsTable,
    where: [{ field: "id", operator: "eq", value: changeId }],
    namespace,
  });

  // Invalidate the distributed authorization entry before deleting the
  // authoritative grant. If invalidation fails, the database grant remains
  // active, preventing a revoked-database/stale-directory authorization gap.
  // Share indexing is deliberately post-commit; unshare invalidation is
  // deliberately fail-closed before the database delete.
  await deleteDatafnPermissionGrant({
    id: changeId,
    resourceType: mutation.resource,
    resourceNs: namespace,
    resourceId,
    principalId: unsharePrincipalId,
  }, multiRegionRuntime ?? null);

  if (!existingPermission) {
    return {
      ok: true,
      deleted: false,
      changeId,
    };
  }

  await db.delete({
    model: permissionsTable,
    where: [{ field: "id", operator: "eq", value: changeId }],
    namespace,
  });
  await removeLegacyV1Grant({
    db,
    namespace,
    resource: mutation.resource,
    resourceId,
    principalId: unsharePrincipalId,
  });
  return {
    ok: true,
    deleted: true,
    changeId,
  };
}

/** Reconciles the distributed permission directory from committed database state. */
export async function syncDatafnPermissionGrantAfterCommit(
  db: Adapter,
  mutation: {
    operation: string;
    resource: string;
    id?: string;
    scope?: "record" | "resource";
    shareWith?: { principalId?: string; userId?: string };
  },
  namespace: string,
  multiRegionRuntime: DatafnMultiRegionRuntimeConfig | null,
): Promise<void> {
  if (
    !multiRegionRuntime ||
    (mutation.operation !== "share" && mutation.operation !== "unshare")
  ) {
    return;
