    // Check for missing columns
    for (const [fieldName, fieldSchema] of Object.entries(reqFieldMap)) {
      const colName = fieldSchema.fieldName ?? fieldName;
      if (!curColMap.has(colName)) {
        missingColumns.push(colName);
