  return {
    linkId: record.id,
    principalId:
      record.principalId ??
      `${options.principalPrefix ?? "public_link:"}${record.id}`,
    actorId:
      record.principalId ??
      `${options.principalPrefix ?? "public_link:"}${record.id}`,
    namespace: record.__ns,
    resourceRegion: typeof record.resourceRegion === "string" ? record.resourceRegion : undefined,
    resource: record.resource,
