export function dynamoDbIndexedDirectoryStore(
  options: DynamoDbStoreOptions,
): IndexedDirectoryStoreAdapter & ProvisionableStoreAdapter {
  const client = documentClient(options);

  return {
    getProvisioningPlan() {
      return dynamoDbStoreProvisioningPlan(options.tableName);
    },
    async get(key) {
      const result = await client.send(new GetCommand({
        TableName: options.tableName,
        Key: { PK: directoryRecordPk(key), SK: DIRECTORY_RECORD_SORT_KEY },
        ConsistentRead: options.consistentRead,
      }));
      return fromDirectoryItem(result.Item);
    },
    async put(record) {
      const existing = await this.get(record.key);
      await writeDirectoryRecord(client, options.tableName, record, existing);
    },
    async putIfAbsent(record) {
      try {
        await writeDirectoryRecord(client, options.tableName, record, null, {
          expression: '(attribute_not_exists(#pk) OR #expiresAt <= :now)',
          names: {
            '#pk': 'PK',
            '#expiresAt': 'expiresAt',
          },
          values: {
            ':now': Math.floor(Date.now() / 1000),
          },
        });
        return { inserted: true };
      } catch (error) {
        if (!isConditionalCheckFailed(error)) throw error;
        const existing = await this.get(record.key);
        return { inserted: false, ...(existing ? { existing } : {}) };
      }
    },
    async update(record) {
      await this.put(record);
      return record;
    },
    async delete(key) {
      const existing = await this.get(key);
      const deletes = existing ? indexEdges(existing).map((edge) => ({
        Delete: {
          TableName: options.tableName,
          Key: { PK: edge.pk, SK: edge.sk },
          Key: { PK: edge.pk, SK: edge.sk },
        },
      })) : [];
      await client.send(new TransactWriteCommand({
        TransactItems: [
          ...deletes,
          {
            Delete: {
              TableName: options.tableName,
              Key: { PK: directoryRecordPk(key), SK: DIRECTORY_RECORD_SORT_KEY },
            },
          },
        ],
      }));
    },
    async query(input) {
      const records: IndexedDirectoryRecord[] = [];
      let exclusiveStartKey = input.cursor
        ? JSON.parse(Buffer.from(input.cursor, 'base64url').toString('utf8'))
        : undefined;
      let lastEvaluatedKey: Record<string, unknown> | undefined;
      do {
        const remaining = input.limit === undefined
          ? undefined
          : input.limit - records.length;
        if (remaining !== undefined && remaining <= 0) break;
        const result = await client.send(new QueryCommand({
          TableName: options.tableName,
          KeyConditionExpression: '#pk = :pk',
          ExpressionAttributeNames: { '#pk': 'PK' },
          ExpressionAttributeValues: { ':pk': directoryIndexPk(input.index, input.value) },
          Limit: remaining,
          ExclusiveStartKey: exclusiveStartKey,
        }));
        const keys = (result.Items ?? [])
          .map((item) => typeof item.dirKey === 'string' ? item.dirKey : null)
          .filter((key): key is string => Boolean(key));
        const pageRecords = (
          await Promise.all(keys.map((key) => this.get(key)))
        ).filter((record): record is IndexedDirectoryRecord =>
          Boolean(
            record
            && normalizeIndexValues(record.indexes?.[input.index]).includes(input.value),
          )
        );
        records.push(...pageRecords);
        lastEvaluatedKey = result.LastEvaluatedKey as Record<string, unknown> | undefined;
        exclusiveStartKey = lastEvaluatedKey;
        if (input.limit === undefined) break;
      } while (lastEvaluatedKey && records.length < input.limit);
      return {
        records,
        ...(lastEvaluatedKey
          ? { cursor: Buffer.from(JSON.stringify(lastEvaluatedKey)).toString('base64url') }
          : {}),
      };
    },
  };
}

