          from: "task",
          to: "objective",
          type: "many-one",
          relation: "objective",
          fkField: "objectiveId",
        },
      ],
    };

    expect(
      normalizeRelationFkRecord(schema, "task", {
        id: "task:1",
        objectiveId: "",
        label: "",
