import { describe, it, expect } from "vitest";
import { generateDrizzleSchema, camelToSnake } from "../src/drizzle-codegen.js";
import { defineSchema, validateSchema } from "@datafn/core";

function readSchemaExports(output: string): string[] {
  const match = output.match(/export const schema = \{ ([^}]+) \};/);
  return match ? match[1].split(", ") : [];
}

function expectedSchemaExports(names: string[]): string[] {
  return [
    "__datafn_changes",
    "__datafn_idempotency",
    "__datafn_meta",
    "__datafn_seed",
    "datafnTimezoneChange",
    "kv",
    ...names,
  ].sort();
}

function readTableBlock(output: string, tableName: string): string {
  const start = output.indexOf(`"${tableName}"`);
  if (start < 0) return "";
  const tail = output.slice(start);
  const nextTable = tail.indexOf("\n\nexport const ", 1);
  return nextTable < 0 ? tail : tail.slice(0, nextTable);
}

