}

export interface TransactResult {
  ok: boolean;
  result?: {
    ok: boolean;
    results: Array<any>;
    error?: {
      code: DatafnErrorCode;
      message: string;
    };
  };
  error?: {
    code: DatafnErrorCode;
    message: string;
