/**
 * Database-backed idempotency store
 * Provides durable mutation deduplication using adapter storage
 */

import type { Adapter } from "@superfunctions/db";
import {
  isRetryableMutationResult,
  type IdempotencyStore,
  type MutationResult,
} from "./idempotency.js";
import { ensureInternalTable } from "./internal-tables.js";
import type { DatafnLogger } from "../logger.js";

/**
 * Adapter-backed idempotency store for durable deduplication
 */
export class DbIdempotencyStore implements IdempotencyStore {
  private ensured = false;
  private logger?: DatafnLogger;

  constructor(
    private db: Adapter,
    private namespace: string = "datafn",
    logger?: DatafnLogger,
    ensured = false,
  ) {
    this.logger = logger;
    this.ensured = ensured;
  }

  withDb(db: Adapter): IdempotencyStore {
    // The outer store performs initialization before transactional mutation
    // execution. Preserve that state so rebinding does not issue DDL inside a
    // transaction (which implicitly commits on MySQL).
    return new DbIdempotencyStore(db, this.namespace, this.logger, this.ensured);
  }

  async ensureReady(): Promise<void> {
    if (!this.ensured) {
      await ensureInternalTable(this.db, "__datafn_idempotency");
      this.ensured = true;
    }
  }

  async get(
    clientId: string,
    mutationId: string,
  ): Promise<MutationResult | null> {
    // EXE-007: DB errors propagate; only swallow JSON parse errors (SyntaxError)
    await this.ensureReady();

    const record = await this.db.internal.findOne("__datafn_idempotency", [
      { field: "namespace", op: "eq", value: this.namespace },
      { field: "client_id", op: "eq", value: clientId },
      { field: "mutation_id", op: "eq", value: mutationId },
    ]);

    if (!record) {
      return null;
    }

    // Only catch JSON parse errors; DB errors propagated above
    try {
      return JSON.parse(record.result as string);
    } catch (error) {
      if (!(error instanceof SyntaxError)) {
        this.logger?.warn("Idempotency store get: unexpected error during parse", {
          error: String(error),
          operation: "idempotency-get",
        });
      }
      return null;
    }
  }

  /**
   * Delete idempotency records older than retentionDays for this namespace.
   * Returns the number of rows deleted.
   */
  async pruneIdempotency(retentionDays: number): Promise<number> {
    await this.ensureReady();
    const cutoff = new Date(Date.now() - retentionDays * 86400000).toISOString();
    return await this.db.internal.delete("__datafn_idempotency", [
      { field: "namespace", op: "eq", value: this.namespace },
      { field: "created_at", op: "lt", value: cutoff },
    ]);
  }

  async set(
    clientId: string,
    mutationId: string,
    result: MutationResult,
  ): Promise<void> {
    try {
      await this.ensureReady();

      const where = [
        { field: "namespace", op: "eq" as const, value: this.namespace },
        { field: "client_id", op: "eq" as const, value: clientId },
        { field: "mutation_id", op: "eq" as const, value: mutationId },
      ];
      const existing = await this.db.internal.findOne(
        "__datafn_idempotency",
        where,
      );
      if (existing) {
        let existingResult: MutationResult | null = null;
        try {
          existingResult = JSON.parse(existing.result as string);
        } catch {
          existingResult = null;
        }
        if (!isRetryableMutationResult(existingResult)) return;
        await this.db.internal.update("__datafn_idempotency", where, {
          result: JSON.stringify(result),
          created_at: new Date().toISOString(),
        });
        return;
      }

      await this.db.internal.create("__datafn_idempotency", {
        id: `${this.namespace}:${clientId}:${mutationId}`,
        namespace: this.namespace,
        client_id: clientId,
        mutation_id: mutationId,
        result: JSON.stringify(result),
        created_at: new Date().toISOString(),
      });
    } catch (error: any) {
      // Duplicate key errors are expected on replay — stay silent
      const code = error?.code;
      const msg = (error?.message || "").toLowerCase();
      const isDuplicate =
        code === "23505" || code === "UNIQUE_VIOLATION" || code === "ER_DUP_ENTRY" ||
        code === "SQLITE_CONSTRAINT_UNIQUE" ||
        msg.includes("unique") || msg.includes("duplicate") || msg.includes("conflict");
      if (!isDuplicate) {
        this.logger?.warn("Idempotency store set failed (non-duplicate)", {
          error: String(error),
          operation: "idempotency-set",
        });
      }
    }
  }
        },

        async count(params: CountParams): Promise<number> {
          const tableName = context.getModelName(params.model);
          const table = store.get(tableName);

          if (!table) {
            return 0;
          }

          if (!params.where) {
            return table.size;
          }

          let count = 0;
          for (const record of table.values()) {
            if (matchesWhere(record, params.where)) {
              count++;
            }
          }

          return count;
        },

        async transaction<R>(
          callback: (trx: TransactionAdapter) => Promise<R>
        ): Promise<R> {
          const storeSnapshot = cloneStore();
          const schemaVersionsSnapshot = new Map(schemaVersions);
          const internalSnapshot = internalCrudState.snapshot();
          let rolledBack = false;
          const transactionAdapter = Object.assign(
            Object.fromEntries(
              Object.entries(adapter).filter(([key]) => key !== 'transaction' && key !== 'close'),
            ),
            {
              async commit() {},
              async rollback() {
                restoreStore(storeSnapshot, schemaVersionsSnapshot);
                internalCrudState.restore(internalSnapshot);
                rolledBack = true;
              },
            },
          ) as unknown as TransactionAdapter;

          try {
            return await callback(transactionAdapter);
          } catch (error) {
            if (!rolledBack) {
              restoreStore(storeSnapshot, schemaVersionsSnapshot);
              internalCrudState.restore(internalSnapshot);
            }
            throw error;
          }
        },

        async initialize(): Promise<void> {
          // Nothing to initialize for in-memory adapter
        },

        async isHealthy(): Promise<HealthStatus> {
          return {
            healthy: true,
            uptime: Date.now() - startTime,
          };
        },

        async close(): Promise<void> {
          // Clear storage on close
          store.clear();
          schemaVersions.clear();
          schemaVersions.clear();
        },

        async getSchemaVersion(namespace: string): Promise<number> {
          return schemaVersions.get(namespace) ?? 0;
        },

        async setSchemaVersion(namespace: string, version: number): Promise<void> {
          schemaVersions.set(namespace, version);
        },

        async validateSchema(_schema: TableSchema): Promise<ValidationResult> {
          // Simple validation for memory adapter
          return { valid: true };
        },
      };
    },
  });

  adapter = Object.assign(factory({
    schema: normalizeAdapterSchema(config?.adapterSchema),
  }), { internal: internalCrudState.crud });
  const queuedAdapterMethods = new Map(
    Reflect.ownKeys(adapter).map((property) => [property, Reflect.get(adapter, property)])
  );

  const transactionAwareInternal = new Proxy(internalCrudState.crud, {
    get(target, property, receiver) {
      const value = Reflect.get(target, property, receiver);
      if (typeof value !== 'function') return value;
      return (...args: unknown[]) => enqueueOperation(() => Promise.resolve(Reflect.apply(value, target, args)));
    },
  });

  return new Proxy(adapter, {
    get(target, property, receiver) {
      if (property === 'internal') return transactionAwareInternal;

      const value = Reflect.get(target, property, receiver);
      if (typeof value !== 'function') return value;
      if (value !== queuedAdapterMethods.get(property)) {
        return value.bind(target);
      }
      return (...args: unknown[]) => enqueueOperation(() => Promise.resolve(Reflect.apply(value, target, args)));
    },
  });
}

