/**
 * Introspect SQLite database schema
 */
export async function introspectSQLite(
  db: any,
  tablePrefix?: string
): Promise<DatabaseTable[]> {
  // Query tables
  const tablesQuery = `
    SELECT name as table_name
    FROM sqlite_master 
    WHERE type = 'table' 
      AND name NOT LIKE 'sqlite_%'
      ${tablePrefix ? `AND name LIKE ?` : ''}
    ORDER BY name
  `;
  const tables = await db.all(
    tablesQuery,
    tablePrefix ? [`${tablePrefix}%`] : []
  );

  const result: DatabaseTable[] = [];

  for (const { table_name } of tables) {
    // Query columns using PRAGMA
    const columns = await db.all(`PRAGMA table_info(${table_name})`);

    // Query indexes
    const indexesQuery = await db.all(
      `SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = ?`,
      [table_name]
    );

    const indexes: DatabaseIndex[] = [];
    for (const { name } of indexesQuery) {
      const indexInfo = await db.all(`PRAGMA index_info(${name})`);
      indexes.push({
        name,
        tableName: table_name,
        columns: indexInfo.map((i: any) => i.name),
        isUnique: false, // Would need index_list to determine
      });
    }

    result.push({
      name: table_name,
      columns: columns.map((c: any) => ({
        tableName: table_name,
        columnName: c.name,
        dataType: c.type,
        isNullable: c.notnull === 0,
        defaultValue: c.dflt_value,
        isPrimaryKey: c.pk === 1,
        isUnique: false,
      })),
      indexes,
      constraints: [],
    });
  }

  return result;
}

/**
 * Convert database column type to FieldSchema type
 */
export function mapDatabaseTypeToFieldType(dbType: string): FieldSchema['type'] {
  const normalized = dbType.toLowerCase();

  if (normalized.includes('int') || normalized.includes('serial')) {
    return normalized.includes('big') ? 'bigint' : 'number';
  }
  if (
    normalized.includes('varchar') ||
    normalized.includes('text') ||
    normalized.includes('char')
  ) {
    return 'string';
  }
  if (normalized.includes('bool')) {
    return 'boolean';
  }
  if (
    normalized.includes('timestamp') ||
    normalized.includes('date') ||
    normalized.includes('time')
  ) {
    return 'date';
  }
  if (normalized.includes('json')) {
    return 'json';
  }

  // Default to string for unknown types
  return 'string';
}

/**
 * Convert DatabaseTable to TableSchema
 */
export function databaseTableToSchema(dbTable: DatabaseTable): TableSchema {
  const fields: Record<string, FieldSchema> = {};

  for (const col of dbTable.columns) {
    fields[col.columnName] = {
      type: mapDatabaseTypeToFieldType(col.dataType),
      required: !col.isNullable,
      unique: col.isUnique || col.isPrimaryKey,
      fieldName: col.columnName,
    };
  }

  return {
    modelName: dbTable.name,
    fields,
    indexes: dbTable.indexes.map((idx) => ({
      name: idx.name,
      fields: idx.columns,
      unique: idx.isUnique,
    })),
    constraints: [],
  };
}
export function normalizeObservability<TEvent extends ObservationEvent = ObservationEvent>(
  input: ObservabilityInput<TEvent>,
): SuperfunctionObservability<TEvent> | undefined {
  if (!input) {
    return undefined;
  }
  return createObservability(input as Exclude<ObservabilityInput<TEvent>, false | null | undefined>);
}

export function instrumentMethods<TTarget extends object>(
  input: InstrumentMethodsInput<TTarget>,
): TTarget {
  const { target, observability, kind, component, extract } = input;
  if (!observability) {
    return target;
  }

  return new Proxy(target, {
    get(currentTarget, property, receiver) {
      const value = Reflect.get(currentTarget, property, receiver);
      if (typeof value !== "function") {
        return value;
      }

      return (...args: unknown[]) => {
        const extracted = extract?.({ property, args }) ?? {};
        const startedAt = now();
        const record = (ok: boolean) => {
          observability.metrics.record({
            kind,
            component,
            operation: extracted.operation ?? String(property),
            resource: extracted.resource,
            labels: extracted.labels,
            durationMs: now() - startedAt,
            ok,
          });
        };
        try {
          const result = value.apply(currentTarget, args);
          const then = readThen(result);
          if (then) {
            const assimilated = new Promise<unknown>((resolve, reject) => {
              then.call(result, resolve, reject);
            });
            return assimilated.then(
              (resolved) => {
                record(true);
                return resolved;
              },
              (error) => {
                record(false);
                throw error;
              },
            );
          }
          record(true);
          return result;
        } catch (error) {
          record(false);
          throw error;
        }
      };
    },
  }) as TTarget;
}

function readThen(
  value: unknown,
): ((resolve: (value: unknown) => void, reject: (reason?: unknown) => void) => void) | null {
  if (!((typeof value === "object" && value !== null) || typeof value === "function")) {
    return null;
  }
  const then = (value as { then?: unknown }).then;
  return typeof then === "function"
    ? then as (resolve: (value: unknown) => void, reject: (reason?: unknown) => void) => void
    : null;
}

export function readObservationGroup(
  snapshot: RequestObservationSnapshot | undefined,
  kind: string,
): ObservationGroupSnapshot {
  return snapshot?.groups[kind] ?? {
    kind,
    count: 0,
    durationMs: 0,
    maxDurationMs: 0,
    errorCount: 0,
  };
}

export function roundObservationMs(value: number): number {
  return Math.round(value * 100) / 100;
}

