export type DateFieldStorageType =
  | 'timestamp'
  | 'timestamptz'
  | 'iso-text'
  | 'epoch-ms-integer'
  | 'epoch-ms-bigint';

export interface FieldSchema {
  type: 'string' | 'number' | 'boolean' | 'date' | 'datetime' | 'json' | 'bigint';
  required?: boolean;
  unique?: boolean;
  defaultValue?: any;
  /**
   * Runtime value shape expected by the library for `date`/`datetime` fields.
   * Defaults to `date` for legacy `type: "date"` schemas.
   */
  dateValueType?: DateFieldValueType;
  /**
   * Physical value shape used by the adapter/storage layer.
   * Defaults are derived from `dateValueType`.
   */
  dateStorageType?: DateFieldStorageType;
  references?: {
    model: string;
    field: string;
    onDelete?: 'cascade' | 'set null' | 'restrict';
    onUpdate?: 'cascade' | 'set null' | 'restrict';
  };
  fieldName?: string; // Custom column name
}

export interface IndexSchema {
  name: string;
  fields: string[];
  unique?: boolean;
}

export interface ConstraintSchema {
  name: string;
  type: 'check' | 'unique' | 'foreign_key';
  fields: string[];
  check?: string; // SQL check expression
}

export type TableSchemaMap = Record<string, TableSchema>;

export type AdapterSchemaInput =
  | TableSchemaMap
  | TableSchema[]
  | {
      schemas: TableSchema[];
    const columns = schemaIndex.fields.map((field) => `table.${field}`).join(', ');
    return `    ${key}: ${builder}('${schemaIndex.name}').on(${columns})`;
  });
}

function uniqueObjectKey(base: string, usedKeys: Set<string>): string {
  const root = base || 'idx';
  let candidate = root;
  let counter = 2;
  while (usedKeys.has(candidate)) {
    candidate = `${root}${counter}`;
    counter += 1;
  }
  usedKeys.add(candidate);
  return candidate;
}

function toCamelCase(value: string): string {
  return value
    .replace(/^[^a-zA-Z_$]+/, '')
    .replace(/[^a-zA-Z0-9_$]+([a-zA-Z0-9_$])/g, (_, char: string) => char.toUpperCase())
    .replace(/[^a-zA-Z0-9_$]/g, '');
}

function mapFieldToDrizzle(
  field: FieldSchema,
  dialect: 'postgres' | 'mysql' | 'sqlite'
): { type: string; config?: string } {
  if (isDateField(field)) {
    switch (resolveDateStorageType(field)) {
      case 'timestamp':
        return dialect === 'sqlite'
          ? { type: 'integer', config: "{ mode: 'timestamp_ms' }" }
          : { type: 'timestamp' };
      case 'timestamptz':
        return dialect === 'sqlite'
          ? { type: 'integer', config: "{ mode: 'timestamp_ms' }" }
          : dialect === 'postgres'
            ? { type: 'timestamp', config: '{ withTimezone: true }' }
            : { type: 'timestamp' };
      case 'iso-text':
        return { type: 'text' };
      case 'epoch-ms-integer':
        return { type: 'integer' };
      case 'epoch-ms-bigint':
        return dialect === 'sqlite'
          ? { type: 'integer' }
          : { type: 'bigint', config: "{ mode: 'number' }" };
    }
  }

  switch (field.type) {
    case 'string':
      return { type: 'text' };
    case 'number':
      return { type: 'integer' };
    case 'bigint':
      return { type: 'bigint', config: "{ mode: 'bigint' }" };
    case 'boolean':
      return { type: 'boolean' };
    case 'json':
      return { type: 'json' };
    default:
      return { type: 'text' };
  }
}

