export interface LibrarySchemaRequirement {
  namespace: string;
  version: number;
  tables: TableSchema[];
}

export interface TableDiff {
  tableName: string;
  action: 'create' | 'alter' | 'drop';
  missingColumns?: string[];
  extraColumns?: string[];
  columnChanges?: Array<{
    column: string;
    change: string;
  }>;
  missingIndexes?: Array<{
    name: string;
    columns: string[];
    unique: boolean;
  }>;
  changedIndexes?: Array<{
    name: string;
    current: { columns: string[]; unique: boolean };
    required: { columns: string[]; unique: boolean };
  }>;
}

export interface MigrationPlan {
  namespace: string;
  fromVersion: number;
  toVersion: number;
