/**
 * Schema introspection utilities for different database types
 * Queries information_schema or equivalent to discover current database structure
 */

import type { TableSchema, FieldSchema } from '@superfunctions/db';

export interface DatabaseColumn {
  tableName: string;
  columnName: string;
  dataType: string;
  isNullable: boolean;
  defaultValue: string | null;
  isPrimaryKey: boolean;
  isUnique: boolean;
}

export interface DatabaseTable {
  name: string;
  columns: DatabaseColumn[];
  indexes: DatabaseIndex[];
  constraints: DatabaseConstraint[];
}

export interface DatabaseIndex {
  name: string;
  tableName: string;
  columns: string[];
  isUnique: boolean;
}

export interface DatabaseConstraint {
  name: string;
  type: 'PRIMARY KEY' | 'FOREIGN KEY' | 'UNIQUE' | 'CHECK';
  tableName: string;
  columns: string[];
  referencedTable?: string;
  referencedColumns?: string[];
}

/**
 * Introspect PostgreSQL database schema
 */
export async function introspectPostgres(
  db: any,
  schema: string = 'public',
  tablePrefix?: string
): Promise<DatabaseTable[]> {
  // Query tables
  const tablesQuery = `
    SELECT table_name 
    FROM information_schema.tables 
    WHERE table_schema = $1 
      AND table_type = 'BASE TABLE'
      ${tablePrefix ? `AND table_name LIKE $2` : ''}
    ORDER BY table_name
  `;
  const tables = await db.query(
    tablesQuery,
    tablePrefix ? [schema, `${tablePrefix}%`] : [schema]
  );

  const result: DatabaseTable[] = [];

  for (const { table_name } of tables.rows) {
    // Query columns
    const columnsQuery = `
      SELECT 
        c.column_name,
        c.data_type,
        c.is_nullable,
        c.column_default,
        CASE WHEN pk.column_name IS NOT NULL THEN true ELSE false END as is_primary_key,
        CASE WHEN uq.column_name IS NOT NULL THEN true ELSE false END as is_unique
      FROM information_schema.columns c
      LEFT JOIN (
        SELECT ku.column_name
        FROM information_schema.table_constraints tc
        JOIN information_schema.key_column_usage ku 
          ON tc.constraint_name = ku.constraint_name
        WHERE tc.table_schema = $1 
          AND tc.table_name = $2
          AND tc.constraint_type = 'PRIMARY KEY'
      ) pk ON c.column_name = pk.column_name
      LEFT JOIN (
        SELECT ku.column_name
        FROM information_schema.table_constraints tc
        JOIN information_schema.key_column_usage ku 
          ON tc.constraint_name = ku.constraint_name
        WHERE tc.table_schema = $1 
          AND tc.table_name = $2
          AND tc.constraint_type = 'UNIQUE'
      ) uq ON c.column_name = uq.column_name
      WHERE c.table_schema = $1 
        AND c.table_name = $2
      ORDER BY c.ordinal_position
    `;
    const columns = await db.query(columnsQuery, [schema, table_name]);

    // Query indexes
    const indexesQuery = `
      SELECT 
        i.indexname as name,
        i.tablename,
        ARRAY_AGG(a.attname ORDER BY array_position(ix.indkey, a.attnum)) as columns,
        ix.indisunique as is_unique
      FROM pg_indexes i
      JOIN pg_class c ON c.relname = i.indexname
      JOIN pg_index ix ON ix.indexrelid = c.oid
      JOIN pg_attribute a ON a.attrelid = ix.indrelid AND a.attnum = ANY(ix.indkey)
