      const sqlType = fieldTypeToSQL(field, dialect);
      const parts = [sqlType];
      if (field.required) parts.push('NOT NULL');
      if (field.unique) parts.push('UNIQUE');

      if (dialect === 'mysql') {
        statements.push(`ALTER TABLE ${diff.tableName} ADD COLUMN ${colName} ${parts.join(' ')};`);
      } else {
        statements.push(`ALTER TABLE ${diff.tableName} ADD COLUMN ${colName} ${parts.join(' ')};`);
      }
    }
  }

