    withSchema(schema) {
      return ensureBuiltinPublicLinks(schema, { modelName });
    },
    resolve(database, token) {
      return resolveDatafnPublicLink(database, token, {
        modelName,
        principalPrefix,
        directory: config.directory
        directory: config.directory
