            if (!body.ok) return body.response;
            try {
              const link = await createDatafnPublicLink({
                database,
                schema,
                modelName,
                principalPrefix,
                directory: config.directory,
                resourceRegion: config.resourceRegion,
                namespace: await config.getOwnerNamespace(actorId, session),
                actorId,
                input: body.data
