    case 'json':
      return 'unknown';
    default:
      return 'unknown';
  }
}

function isDateField(field: FieldSchema): boolean {
  return field.type === 'date' || field.type === 'datetime';
}

function resolveDateValueType(field: FieldSchema): NonNullable<FieldSchema['dateValueType']> {
