function toCamelCase(value: string): string {
  return value
    .replace(/^[^a-zA-Z_$]+/, '')
    .replace(/[^a-zA-Z0-9_$]+([a-zA-Z0-9_$])/g, (_, char: string) => char.toUpperCase())
