    workdir:"/Users/serro/Documents/dev/n/worktrees/superfunctions/review-followup-dev-2026-08-20",
    yield_time_ms:30000,max_output_tokens:2000
  })));
  rs.forEach((r,j)=>{if(r.exit_code===0){ok++}else failures.push({id:chunk[j][0],output:r.output})});
}
text(JSON.stringify({attempted:items.length,ok,failures},null,2));

