 */
function fieldTypeToSQL(field: FieldSchema, dialect: Dialect): string {
  const baseType = field.type;

  if (isDateField(field)) {
    return dateFieldToSQL(field, dialect);
  }

  switch (dialect) {
    case 'postgres':
