    model: permissionsTable,
    where: [{ field: "id", operator: "eq", value: changeId }],
    namespace,
  });
  await removeLegacyV1Grant({
    db,
    namespace,
    resource: mutation.resource,
    resourceId,
    principalId: unsharePrincipalId,
  });
  return {
    ok: true,
    deleted: true,
    changeId,
  };
}

