it("fences an in-flight lease renewal when publishing readiness", async () => {
  vi.useFakeTimers();
  try {
    const localDb = memoryAdapter();
    await localDb.initialize();
    const originalUpdate = localDb.internal.update.bind(localDb.internal);
    let releaseRenewal!: () => void;
    const renewalReleased = new Promise<void>((resolve) => {
      releaseRenewal = resolve;
    });
    let renewalStarted!: () => void;
    const renewalReached = new Promise<void>((resolve) => {
      renewalStarted = resolve;
    });
    let interceptRenewal = false;
    let renewalWhere: Array<{ field: string; op: string; value: unknown }> = [];
    localDb.internal.update = async (table, where, data) => {
      if (
        interceptRenewal &&
        table === "__datafn_permission_directory_outbox"
      ) {
        interceptRenewal = false;
        renewalWhere = where;
        renewalStarted();
        await renewalReleased;
        const current = await localDb.internal.findOne(table, [
          { field: "id", op: "eq", value: taskId },
        ]);
        const expectedLease = where.find(
          (clause) => clause.field === "next_attempt_at",
        )?.value;
        if (current?.next_attempt_at !== expectedLease) return 0;
      }
      return originalUpdate(table, where, data);
    };
    const taskId = await enqueuePermissionDirectorySync(localDb, {
      operation: "share",
      resource: "notes",
      id: "note:renewal-race",
      shareWith: { principalId: "user:partner" },
    }, namespace, "region:test", { pending: true });
    interceptRenewal = true;

    const advancingTimers = vi.advanceTimersByTimeAsync(2 * 60 * 1000);
    await renewalReached;
    expect(renewalWhere.some((clause) => clause.field === "next_attempt_at"))
      .toBe(true);
    await markPermissionDirectorySyncReady(localDb, taskId);
    const ready = await localDb.internal.findOne(
      "__datafn_permission_directory_outbox",
      [{ field: "id", op: "eq", value: taskId }],
    );
    const readyAt = String(ready?.next_attempt_at);
    expect(Date.parse(readyAt)).toBeLessThanOrEqual(Date.now());

    releaseRenewal();
    await advancingTimers;
    const task = await localDb.internal.findOne(
      "__datafn_permission_directory_outbox",
      [{ field: "id", op: "eq", value: taskId }],
    );
    expect(task?.next_attempt_at).toBe(readyAt);
  } finally {
    vi.useRealTimers();
  }
});

