const query = `mutation($threadId:ID!,$body:String!){addPullRequestReviewThreadReply(input:{pullRequestReviewThreadId:$threadId,body:$body}){comment{url}} resolveReviewThread(input:{threadId:$threadId}){thread{isResolved}}}`;
const items = [
  ["PRRT_kwDOP-e7KM6a2fRe", "Fixed in 487ccb28. MySQL column-change definitions now retain the schema-declared default (or the introspected current default when the schema does not override it), and rollback snapshots carry the prior default plus the complete native COLUMN_TYPE. Regression coverage verifies DEFAULT 'pending' forward and DEFAULT 'legacy' on rollback."],
  ["PRRT_kwDOP-e7KM6a2f0H", "Fixed in 487ccb28. If a compacted push returns any mutation failure, the client now immediately resends the complete idempotent batch before computing acknowledgements. A rejected delete therefore cannot acknowledge and discard its omitted merge/replace. New retryable and terminal-delete regressions verify the full batch is resent and the independent write is preserved/applied."],
  ["PRRT_kwDOP-e7KM6a2gbW", "Fixed in 487ccb28. All generated MySQL MODIFY COLUMN statements now include the desired schema default, or preserve the introspected current default when no new default is declared. The same complete definition is used by Drizzle, Prisma, and Kysely, with forward/rollback default regressions."],
  ["PRRT_kwDOP-e7KM6a2gba", "Fixed in 487ccb28. MySQL index generation now rejects bounded utf8mb4 string key parts above 768 characters and also rejects composite string widths above the 3,072-byte budget. All three migration generators have regression coverage for a VARCHAR(769) index."],
  ["PRRT_kwDOP-e7KM6a2gbe", "Fixed in 487ccb28. Failed public-link shares now compensate every possible grant representation: canonical permission row, legacy mirror, and distributed directory entry, before settling the durable task and deleting the link row. A regression forces executeShare to throw after the canonical write and verifies link, grant, and outbox rows are all absent."],
  ["PRRT_kwDOP-e7KM6a2gbg", "Fixed in 487ccb28. Each heartbeat renewal now compare-and-swaps both task id and the exact next_attempt_at lease value it owns. Once settlement publishes readiness, an already-started renewal no longer matches and cannot move the task back into the future. The regression asserts the renewal predicate contains that lease fence."],
  ["PRRT_kwDOP-e7KM6a2gbo", "Fixed in 487ccb28. Transaction setup cleanup now inspects every Promise.allSettled result and logs each rejected readiness release with its error, operation, and taskId, while keeping the durable task available for normal recovery."],
  ["PRRT_kwDOP-e7KM6a2gb5", "Fixed in 487ccb28. MySQL schema diffing now always calls the shared mysqlVarcharLength validator for string fields, even when the current database width matches. Regression coverage verifies a matching VARCHAR(16384) schema is rejected instead of bypassing generator validation."],
  ["PRRT_kwDOP-e7KM6a2gb9", "Fixed in 487ccb28. MySQL introspection now captures information_schema.COLUMNS.COLUMN_TYPE, and rollback generation uses that complete definition. ENUM and SET values, decimal precision, and qualifiers such as unsigned are no longer reconstructed as invalid bare base types; the exact native type is restored after safety validation."],
