      { field: "id", op: "eq", value: taskId },
      { field: "region_id", op: "eq", value: runtime.regionId },
      { field: "next_attempt_at", op: "eq", value: selectedNextAttemptAt },
    ], {
      next_attempt_at: claimedNextAttemptAt,
    });
