    if (await drainPermissionDirectorySync(
      db,
      taskId,
      runtime,
      logger,
      { expectedNextAttemptAt: claimedNextAttemptAt },
    )) {
      processed += 1;
    }
  }
  return { processed, pending: tasks.length - processed };
}
