export interface SchemaDiff {
  missing: string[]; // tables that should exist but don't
  extra: string[]; // tables that exist but shouldn't
  mismatched: Array<{
    table: string;
    reason: string;
  }>;
}

export interface LibrarySchemaRequirement {
  namespace: string;
  version: number;
  tables: TableSchema[];
}

export interface TableDiff {
  tableName: string;
  action: 'create' | 'alter' | 'drop';
  missingColumns?: string[];
  extraColumns?: string[];
  columnChanges?: Array<{
    column: string;
    change: string;
    current?: {
      dataType: string;
      columnType?: string;
      maxLength?: number | null;
      extra?: string | null;
      generationExpression?: string | null;
      isVisible?: boolean;
      characterSet?: string | null;
      collation?: string | null;
      comment?: string | null;
      isNullable: boolean;
      defaultValue?: string | null;
    };
  }>;
  missingIndexes?: Array<{
    name: string;
    columns: string[];
    unique: boolean;
  }>;
  changedIndexes?: Array<{
    name: string;
    current: { columns: string[]; unique: boolean; textColumns?: string[] };
    required: { columns: string[]; unique: boolean };
  }>;
}

export interface MigrationPlan {
  namespace: string;
  fromVersion: number;
  toVersion: number;
  changes: TableDiff[];
}

/**
 * Compare required schemas against current state
 */
export function diffSchemas(
  required: LibrarySchemaRequirement[],
  currentVersions: Record<string, number>
): Record<string, { required: number; current: number; status: 'outdated' | 'up-to-date' | 'not-installed' }> {
  const result: Record<string, any> = {};

  for (const req of required) {
    const current = currentVersions[req.namespace] ?? 0;
    result[req.namespace] = {
      columns: columns.rows.map((c: any) => ({
        dialect: 'postgres' as const,
        tableName: table_name,
        columnName: c.column_name,
        dataType: c.data_type,
        maxLength: c.character_maximum_length == null
          ? null
          : Number(c.character_maximum_length),
        isNullable: c.is_nullable === 'YES',
        defaultValue: c.column_default,
        isPrimaryKey: c.is_primary_key,
        isUnique: c.is_unique,
      })),
      indexes: indexes.rows.map((idx: any) => ({
        name: idx.name,
        tableName: idx.tablename,
        columns: idx.columns,
        isUnique: idx.is_unique,
      })),
      constraints: [],
    });
  }

  return result;
}

/**
 * Introspect MySQL database schema
 */
export async function introspectMySQL(
  db: any,
  database: string,
  tablePrefix?: string
): Promise<DatabaseTable[]> {
  // Query tables
  const tablesQuery = `
    SELECT TABLE_NAME as table_name
    FROM information_schema.TABLES 
    WHERE TABLE_SCHEMA = ?
      AND TABLE_TYPE = 'BASE TABLE'
      ${tablePrefix ? `AND TABLE_NAME LIKE ?` : ''}
    ORDER BY TABLE_NAME
  `;
  const [tables] = await db.query(
    tablesQuery,
    tablePrefix ? [database, `${tablePrefix}%`] : [database]
  );

  const result: DatabaseTable[] = [];

  for (const { table_name } of tables) {
    // Query columns
    const columnsQuery = `
      SELECT 
        COLUMN_NAME as column_name,
        DATA_TYPE as data_type,
        COLUMN_TYPE as column_type,
        CHARACTER_MAXIMUM_LENGTH as character_maximum_length,
        EXTRA as extra,
        GENERATION_EXPRESSION as generation_expression,
        IS_VISIBLE as is_visible,
        CHARACTER_SET_NAME as character_set_name,
        COLLATION_NAME as collation_name,
        COLUMN_COMMENT as column_comment,
        IS_NULLABLE as is_nullable,
        COLUMN_DEFAULT as column_default,
        COLUMN_KEY as column_key
      FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = ?
        AND TABLE_NAME = ?
      ORDER BY ORDINAL_POSITION
    `;
    const [columns] = await db.query(columnsQuery, [database, table_name]);

    // Query indexes
    const indexesQuery = `
      SELECT 
        INDEX_NAME as name,
        TABLE_NAME as table_name,
        NON_UNIQUE as non_unique,
        COLUMN_NAME as column_name
      FROM information_schema.STATISTICS
      WHERE TABLE_SCHEMA = ?
        AND TABLE_NAME = ?
      ORDER BY INDEX_NAME, SEQ_IN_INDEX
    `;
    const [indexRows] = await db.query(indexesQuery, [database, table_name]);

    // Group indexes by name
    const indexMap = new Map<string, DatabaseIndex>();
    for (const row of indexRows as any[]) {
      if (!indexMap.has(row.name)) {
        indexMap.set(row.name, {
          name: row.name,
          tableName: row.table_name,
          columns: [],
          isUnique: row.non_unique === 0,
        });
      }
      indexMap.get(row.name)!.columns.push(row.column_name);
    }

    result.push({
      name: table_name,
      columns: (columns as any[]).map((c) => ({
        dialect: 'mysql' as const,
        tableName: table_name,
        columnName: c.column_name,
        dataType: c.data_type,
        columnType: c.column_type,
        maxLength: c.character_maximum_length == null
          ? null
          : Number(c.character_maximum_length),
        extra: c.extra,
        generationExpression: c.generation_expression,
        isVisible: c.is_visible == null
          ? undefined
          : c.is_visible === 'YES',
        characterSet: c.character_set_name,
