     1	import type { DatafnRelationSchema, DatafnSchema } from "./types.js";
     2	
     3	export type DatafnRelationEndpoint = string | readonly string[];
     4	
     5	export type DatafnRelationDirection = "forward" | "inverse";
     6	
     7	export type DatafnRelationMatch = {
     8	  relation: DatafnRelationSchema;
     9	  direction: DatafnRelationDirection;
    10	};
    11	
    12	type DatafnEndpointSchema = {
    13	  resources: readonly { name: string; idPrefix?: string }[];
    14	};
    15	
    16	export function endpointList(endpoint: DatafnRelationEndpoint): string[] {
    17	  return typeof endpoint === "string" ? [endpoint] : [...endpoint];
    18	}
    19	
    20	export function endpointIncludes(
    21	  endpoint: DatafnRelationEndpoint,
    22	  resource: string,
    23	): boolean {
    24	  return endpointList(endpoint).includes(resource);
    25	}
    26	
    27	export function firstEndpoint(endpoint: DatafnRelationEndpoint): string {
    28	  return endpointList(endpoint)[0] ?? "";
    29	}
    30	
    31	export function resourceNameFromId(id: unknown): string | undefined {
    32	  if (typeof id !== "string") return undefined;
    33	  const index = id.indexOf(":");
    34	  if (index <= 0) return undefined;
    35	  return id.slice(0, index);
    36	}
    37	
    38	export function resolveEndpointResource(
    39	  endpoint: DatafnRelationEndpoint,
    40	  id: unknown,
    41	  schema?: DatafnEndpointSchema,
    42	): string | undefined {
    43	  const resources = endpointList(endpoint);
    44	  if (resources.length === 1) return resources[0];
    45	  if (typeof id === "string" && schema) {
    46	    const prefixedMatch = schema.resources
    47	      .filter((resource) => resources.includes(resource.name))
    48	      .map((resource) => ({
    49	        name: resource.name,
    50	        prefix: resource.idPrefix ?? `${resource.name}:`,
    51	      }))
    52	      .filter((candidate) => {
    53	        if (id === candidate.prefix) return true;
    54	        return /[a-z0-9]$/i.test(candidate.prefix)
    55	          ? id.startsWith(`${candidate.prefix}:`)
    56	          : id.startsWith(candidate.prefix);
    57	      })
    58	      .sort((left, right) => right.prefix.length - left.prefix.length)[0];
    59	    if (prefixedMatch) {
    60	      return prefixedMatch.name;
    61	    }
    62	  }
    63	  const resourceFromId = resourceNameFromId(id);
    64	  if (resourceFromId && resources.includes(resourceFromId)) {
    65	    return resourceFromId;
    66	  }
    67	  return undefined;
    68	}
    69	
    70	export function relationMatchesForward(
    71	  relation: DatafnRelationSchema,
    72	  resource: string,
    73	  relationName: string,
    74	): boolean {
    75	  return (
    76	    endpointIncludes(relation.from, resource) &&
    77	    relation.relation === relationName
    78	  );
    79	}
    80	
    81	export function relationMatchesInverse(
    82	  relation: DatafnRelationSchema,
    83	  resource: string,
    84	  relationName: string,
    85	): boolean {
    86	  return (
    87	    endpointIncludes(relation.to, resource) &&
