async function createDatafnPublicLink(input: {
  database: Adapter;
  schema: DatafnSchema;
  modelName: string;
  principalPrefix: string;
  directory?: IndexedDirectoryStoreAdapter;
  resourceRegion?: string;
  namespace: string;
  actorId: string;
  input: Record<string, unknown>;
}): Promise<DatafnPublicLinkGrant> {
  const validation = validatePublicLinkGrant(input.schema, input.input);
  if (!validation.ok) {
    throw new DatafnPublicLinkInputError(validation.message, validation.path);
  }
  const permissionDirectoryRuntime = input.directory && input.resourceRegion
    ? { directory: input.directory, regionId: input.resourceRegion }
    : null;
  if (permissionDirectoryRuntime) {
    await ensurePermissionDirectoryOutbox(input.database);
  }

  const id = `plink:${crypto.randomUUID()}`;
  const secret = randomSecret();
  const token = `${id}.${secret}`;
  const principalId = `${input.principalPrefix}${id}`;
  const now = Date.now();
  const record: DatafnPublicLinkRecord = {
    id,
    principalId,
    resource: validation.resource,
    recordId: validation.recordId,
    scope: validation.scope,
    level: validation.level,
    tokenHash: await hashPublicLinkToken(token),
    expiresAt: validation.expiresAt,
    revokedAt: null,
    __ns: input.namespace,
    ...(input.resourceRegion ? { resourceRegion: input.resourceRegion } : {}),
    createdAt: now,
    createdBy: input.actorId,
    updatedAt: now,
    updatedBy: input.actorId
  };
  const permissionMutation = {
    operation: "share",
    resource: validation.resource,
    id: validation.recordId ?? undefined,
    scope: validation.scope,
    shareWith: { principalId },
  } as const;
  const permissionSnapshot = await snapshotDatafnPermissionGrantBeforeShare(
    input.database,
    permissionMutation,
    input.namespace,
  );
  const permissionDirectoryTaskId = permissionDirectoryRuntime
    ? await enqueuePermissionDirectorySync(
        input.database,
        permissionMutation,
        input.namespace,
        permissionDirectoryRuntime.regionId,
        { pending: true },
      )
    : null;

  const settlePermissionDirectoryTask = async () => {
    if (!permissionDirectoryRuntime || !permissionDirectoryTaskId) return;
    try {
      await markPermissionDirectorySyncReady(
        input.database,
        permissionDirectoryTaskId,
      );
      await drainPermissionDirectorySync(
        input.database,
        permissionDirectoryTaskId,
        permissionDirectoryRuntime,
      );
    } catch (error) {
      // The task remains durable. A failed release stops its owner heartbeat,
      // so the last lease eventually expires into the scheduled retry queue.
      console.warn("Public-link permission directory reconciliation deferred", {
        error: String(error),
        operation: "public-link-permission-directory",
        taskId: permissionDirectoryTaskId,
      });
    }
  };

  let shareResult: Awaited<ReturnType<typeof executeShare>>;
  try {
    await input.database.create({
      model: input.modelName,
      data: record as unknown as Record<string, unknown>,
      namespace: input.namespace
    });

    shareResult = await executeShare(
      input.database,
      {
        resource: validation.resource,
        id: validation.recordId ?? undefined,
        scope: validation.scope,
        shareWith: {
          principalId,
          level: validation.level
        }
      },
      validation.capabilities,
      input.namespace,
      input.actorId,
      undefined,
      permissionDirectoryRuntime,
    );
  } catch (error) {
    let compensationError: unknown;
    try {
      await rollbackDatafnPermissionGrantAfterFailedShare(
        input.database,
        {
          resource: validation.resource,
          id: validation.recordId ?? undefined,
          scope: validation.scope,
          shareWith: { principalId },
        },
        input.namespace,
        permissionDirectoryRuntime,
        permissionSnapshot,
      );
    } catch (cleanupError) {
  );

  if (!ownerPermission) {
    return {
      ok: false,
      code: "FORBIDDEN",
      message: "Authorization denied",
      path: "operation",
    };
  }

  return { ok: true, record: record as Record<string, unknown> };
}

export async function executeShare(
  db: Adapter,
  mutation: {
    resource: string;
    id?: string;
    scope?: "record" | "resource";
    shareWith?: { principalId?: string; userId?: string; level?: string };
  },
  resolvedCapabilities: unknown[],
  namespace: string,
  actorId?: string,
  logger?: DatafnLogger,
  multiRegionRuntime?: DatafnMultiRegionRuntimeConfig | null,
): Promise<
  | { ok: true; permissionRecord: Record<string, unknown> }
  | { ok: false; code: string; message: string; path: string }
> {
  const shareableConfig = getShareableConfig(resolvedCapabilities);
  if (!shareableConfig) {
    return {
      ok: false,
      code: "DFQL_UNSUPPORTED",
      message: "Unsupported DFQL feature: mutation.operation.share",
      path: "operation",
    };
  }

  const shareScope = getShareScope(mutation.scope);
  if (shareScope === "resource" && shareableConfig.supportsScopeGrants === false) {
    return {
      ok: false,
      code: "DFQL_UNSUPPORTED",
      message: "Unsupported DFQL feature: mutation.scope.resource",
      path: "scope",
    };
  }

  let ownerCheck: OwnershipResult | null = null;
  if (shareScope === "record") {
    if (!mutation.id) {
      return {
        ok: false,
        code: "DFQL_INVALID",
        message: "Invalid DFQL: id must be string",
        path: "id",
      };
    }
    ownerCheck = await ensureOwnerAccess(
      db,
      mutation.resource,
      mutation.id,
      namespace,
      actorId,
    );
    if (!ownerCheck.ok) {
      return ownerCheck;
    }
  } else if (
    !(await hasResourceScopeOwnerAccess(
      db,
      mutation.resource,
      actorId,
      namespace,
    ))
  ) {
    return {
      ok: false,
      code: "FORBIDDEN",
      message: "Authorization denied",
      path: "operation",
    };
  }

  const canonicalPrincipalResult = canonicalizeSharePrincipal(
    mutation.shareWith as Record<string, unknown> | undefined,
  );
  if (!canonicalPrincipalResult.ok) {
    return canonicalPrincipalResult;
  }
  if (
    mutation.shareWith?.userId !== undefined
  ) {
    emitLegacyShareDeprecationWarning(logger, "share");
  }
  const sharePrincipalId = canonicalPrincipalResult.principalId;

  if (
    shareableConfig.crossNsShareable === false &&
    !isPrincipalInNamespace(sharePrincipalId, namespace)
  ) {
    return {
      ok: false,
      code: "DFQL_CROSS_NS_SHARE_FORBIDDEN",
      message: "Cross-namespace sharing is disabled for this resource",
      path: "shareWith.principalId",
    };
  }

  const requestedLevel = mutation.shareWith?.level ?? "viewer";
  if (!shareableConfig.levels.includes(requestedLevel)) {
    return {
      ok: false,
      code: "DFQL_INVALID",
      message: `Invalid DFQL: shareWith.level must be one of [${shareableConfig.levels.join(", ")}]`,
      path: "shareWith.level",
    };
  }

  const resourceId = shareScope === "resource" ? null : (mutation.id as string);
  const grantKind = shareScope === "resource" ? "scope" : "record";
  const permissionEntryId = getPermissionEntryId(
    mutation.resource,
    namespace,
    resourceId,
    sharePrincipalId,
  );
  const permissionsTable = getPermissionsTableName();
  const now = Date.now();
  const existingPermission = await db.findOne({
    model: permissionsTable,
    where: [{ field: "id", operator: "eq", value: permissionEntryId }],
    namespace,
  });

  const permissionRecord: Record<string, unknown> = existingPermission
    ? {
        ...(existingPermission as Record<string, unknown>),
        resourceType: mutation.resource,
        resourceNs: namespace,
        resourceId,
        principalId: sharePrincipalId,
        level: requestedLevel,
        grantKind,
        sourceRef: null,
        grantedBy: actorId ?? "system",
        grantedAt: now,
        revokedAt: null,
        ...(multiRegionRuntime ? { resourceRegion: multiRegionRuntime.regionId } : {}),
      }
    : {
        id: permissionEntryId,
        resourceType: mutation.resource,
        resourceNs: namespace,
        resourceId,
        principalId: sharePrincipalId,
        level: requestedLevel,
        grantKind,
        sourceRef: null,
        grantedBy: actorId ?? "system",
        grantedAt: now,
        revokedAt: null,
        ...(multiRegionRuntime ? { resourceRegion: multiRegionRuntime.regionId } : {}),
      };

  if (existingPermission) {
    await db.update({
      model: permissionsTable,
      where: [{ field: "id", operator: "eq", value: permissionRecord.id }],
      data: {
        resourceType: permissionRecord.resourceType,
        resourceNs: permissionRecord.resourceNs,
        resourceId: permissionRecord.resourceId,
        principalId: permissionRecord.principalId,
        level: permissionRecord.level,
        grantKind: permissionRecord.grantKind,
        sourceRef: permissionRecord.sourceRef,
        grantedBy: permissionRecord.grantedBy,
        grantedAt: permissionRecord.grantedAt,
        revokedAt: permissionRecord.revokedAt,
        ...(multiRegionRuntime ? { resourceRegion: permissionRecord.resourceRegion } : {}),
      },
      namespace,
    });
  } else {
    await db.create({
      model: permissionsTable,
      data: permissionRecord,
      namespace,
    });
  }

  const mirrorLevel =
    requestedLevel === "viewer" ||
    requestedLevel === "editor" ||
    requestedLevel === "owner"
      ? requestedLevel
      : null;
  if (mirrorLevel) {
    await mirrorGrantToLegacyV1({
      db,
      namespace,
      resource: mutation.resource,
      resourceId,
      principalId: sharePrincipalId,
      level: mirrorLevel,
      grantedBy: actorId ?? "system",
      grantedAt: now,
    });
  }

  return { ok: true, permissionRecord };
}

