              trx,
              getLegacyPermissionsTable(mutation.resource),
              expectedLegacy,
              snapshot.legacy,
              LEGACY_GRANT_OWNERSHIP_FIELDS,
              namespace,
            );
            if (!legacyRestored) throw COMPENSATION_OWNERSHIP_LOST;
          }
          const canonicalRestored = await conditionallyRestoreGrantRecord(
            trx,
