/**
 * Reconcile implementation - counts-based drift detection
 * 
 * Implements SYNC-007: Server reconcile endpoint returns deterministic counts
 * for resources and join stores.
 */

import type { DatafnErrorCode, DatafnSchema } from "../../core-types.js";
import { getJoinStoreKey, getRelationJoinTableName } from "@datafn/core";
import type { Adapter } from "@superfunctions/db";
import { ChangeTrackingService } from "./change-tracking.js";
import type { SequenceStore } from "./sequence-store.js";
import type { DatafnLogger } from "../../logger.js";
import { isPrivateShareableResource, resolveAccessLevel } from "../../validation/authz.js";
import { resourceIdMatches } from "./resource-id.js";

function shouldIncludeJoinRowForStore(
  row: Record<string, unknown>,
  relation: NonNullable<DatafnSchema["relations"]>[number],
  schema: DatafnSchema,
  from: string,
  to: string,
): boolean {
  const froms = Array.isArray(relation.from) ? relation.from : [relation.from];
  const tos = Array.isArray(relation.to) ? relation.to : [relation.to];
  if (typeof row.fromResource === "string" && row.fromResource !== from) {
    return false;
  }
  if (typeof row.toResource === "string" && row.toResource !== to) {
    return false;
  }
  const fromValue = typeof row.from === "string" ? row.from : undefined;
  const toValue = typeof row.to === "string" ? row.to : undefined;
  const fromMatches =
    froms.length === 1 ||
    !fromValue ||
    resourceIdMatches(schema, froms, from, fromValue);
  const toMatches =
    tos.length === 1 ||
    !toValue ||
    resourceIdMatches(schema, tos, to, toValue);
  return fromMatches && toMatches;
}

export interface ReconcileRequest {
  clientId: string;
  resources: string[];
  includeJoins?: boolean;
  actorId?: string;
}

export interface ReconcileResult {
  ok: boolean;
  counts?: Record<string, number>;
  joinCounts?: Record<string, number>;
  latestCursor?: string;
  error?: {
    code: DatafnErrorCode;
    message: string;
    details?: Record<string, unknown>;
  };
}

/**
 * Execute reconcile operation - return deterministic counts for drift detection
 */
export async function executeReconcile(
  request: ReconcileRequest,
  schema: DatafnSchema,
  db: Adapter,
  namespace: string,
  sequenceStore?: SequenceStore,
  logger?: DatafnLogger,
): Promise<ReconcileResult> {
  // Validate clientId
  if (!request.clientId || typeof request.clientId !== "string") {
    return {
      ok: false,
      error: {
        code: "DFQL_INVALID",
        message: "Invalid DFQL: clientId must be string",
        details: { path: "clientId" },
      },
    };
  }

  // Validate resources array
  if (!Array.isArray(request.resources)) {
    return {
      ok: false,
      error: {
        code: "DFQL_INVALID",
        message: "Invalid DFQL: resources must be array",
        details: { path: "resources" },
      },
    };
  }

  const counts: Record<string, number> = {};
  let joinCounts: Record<string, number> | undefined;
  const actorId = request.actorId;

  // Validate and count each requested resource
  for (const resourceName of request.resources) {
    const resource = schema.resources.find((r) => r.name === resourceName);

    if (!resource) {
      return {
        ok: false,
        error: {
          code: "DFQL_UNKNOWN_RESOURCE",
          message: `Unknown resource: ${resourceName}`,
          details: { path: `resources[${request.resources.indexOf(resourceName)}]` },
        },
      };
    }

    // Check for isRemoteOnly flag (reconcile doesn't make sense for remote-only)
    if ((resource as any).isRemoteOnly) {
      return {
    });
  }
  for (const entry of capabilities) {
    if (typeof entry !== "string") {
      return err("SCHEMA_INVALID", "Relation capability values must be strings", {
        path: "capabilities",
      });
    }
    if (!RELATION_SIMPLE_CAPABILITIES.has(entry as RelationSimpleCapability)) {
      return err("INVALID_CAPABILITY", `Unknown relation capability "${entry}"`, {
        path: "capabilities",
      });
    }
  }
  const declared = new Set(capabilities as RelationSimpleCapability[]);
  return ok(RELATION_CAPABILITY_CANONICAL_ORDER.filter((cap) => declared.has(cap)));
}

/**
 * Resolve whether namespace isolation is enabled from a schema-like object.
 * Default is `true`.
 */
function resolveNamespaced(s: Record<string, unknown>): boolean {
  if (typeof s.namespaced === "boolean") return s.namespaced;
  return true;
}

/**
 * Returns whether namespace isolation is enabled for a given schema.
 * Default is `true`.
 */
export function isNamespaced(schema: DatafnSchema): boolean {
  if (typeof schema.namespaced === "boolean") return schema.namespaced;
  return true;
}

/**
 * Validates a schema and returns a normalized version.
 *
 * Normalization:
 * - Converts `indices: string[]` to `{ base: string[], search: [], vector: [] }`
 * - Ensures `relations` is present (defaults to [])
 *
 * Validation:
 * - `resources` must be present and be an array
 * - Each resource must have unique `name` and integer `version`
 * - Fields must have unique names within a resource
 */
export function validateSchema(schema: unknown): DatafnEnvelope<DatafnSchema> {
  // Check that schema is an object
  if (typeof schema !== "object" || schema === null || Array.isArray(schema)) {
    return err("SCHEMA_INVALID", "Invalid schema: expected object", {
      path: "$",
    });
  }

  const s = schema as Record<string, unknown>;
  const globalCapsResult = parseSchemaCapabilities(s.capabilities);
  if (!globalCapsResult.ok) return globalCapsResult;
  const globalCapabilities = globalCapsResult.result;
  const defaultPermissionsResult = validateDefaultPermissions(s.defaultPermissions);
  if (!defaultPermissionsResult.ok) return defaultPermissionsResult;

  if (
    s.relationIntegrity !== undefined &&
    !RELATION_INTEGRITY_MODES.has(s.relationIntegrity as DatafnRelationIntegrityMode)
  ) {
    return err(
      "SCHEMA_INVALID",
      `Invalid schema: relationIntegrity must be one of ${[...RELATION_INTEGRITY_MODES].join(", ")}`,
      { path: "relationIntegrity" },
    );
  }

  // Check resources exists and is an array
  if (!s.resources || !Array.isArray(s.resources)) {
    return err("SCHEMA_INVALID", "Invalid schema: missing resources", {
      path: "resources",
    });
  }

  // LOW-028: Enforce resource count limit
  const MAX_RESOURCES = 100;
  if (s.resources.length > MAX_RESOURCES) {
    return err("SCHEMA_INVALID", `Invalid schema: too many resources (max ${MAX_RESOURCES})`, {
      path: "resources",
    });
  }

  const resourceNames = new Set<string>();
  const normalizedResources: DatafnResourceSchema[] = [];

  for (const resource of s.resources) {
    if (
      typeof resource !== "object" ||
      resource === null ||
      Array.isArray(resource)
    ) {
      return err("SCHEMA_INVALID", "Invalid schema: resource must be object", {
        path: "resources",
      });
    }

    const r = resource as Record<string, unknown>;

    // Validate name
    if (typeof r.name !== "string") {
      return err(
        "SCHEMA_INVALID",
        "Invalid schema: resource.name must be string",
        { path: "resources" }
      );
    }

    // Check for duplicate resource names
    if (resourceNames.has(r.name)) {
      return err(
        "SCHEMA_INVALID",
        `Invalid schema: duplicate resource name: ${r.name}`,
        { path: "resources" }
      );
    }
