function findSchemaForTable(
  schemas: TableSchema[],
  namespace: string,
  tableName: string
): TableSchema | undefined {
  return schemas.find((schema) => {
    return (
      schema.modelName === tableName
      || resolvePhysicalTableName(namespace, schema.modelName) === tableName
    );
  });
}

/**
 * Generate ALTER TABLE statements for column changes
 */
function generateAlterTableSQL(
  diff: TableDiff,
  schema: TableSchema,
  dialect: Dialect
): string[] {
  const statements: string[] = [];

  // Add missing columns
  if (diff.missingColumns) {
    for (const colName of diff.missingColumns) {
      const field = Object.entries(schema.fields).find(
        ([name, f]) => (f.fieldName ?? name) === colName
      )?.[1];
      if (!field) continue;

      const sqlType = fieldTypeToSQL(field, dialect);
      const parts = [sqlType];
      if (field.required) parts.push('NOT NULL');
      if (field.unique) parts.push('UNIQUE');

      if (dialect === 'mysql') {
        statements.push(`ALTER TABLE ${diff.tableName} ADD COLUMN ${colName} ${parts.join(' ')};`);
      } else {
        statements.push(`ALTER TABLE ${diff.tableName} ADD COLUMN ${colName} ${parts.join(' ')};`);
      }
    }
  }

  // Drop extra columns (commented out by default for safety)
  if (diff.extraColumns && diff.extraColumns.length > 0) {
    statements.push(
      `-- WARNING: The following columns exist but are not in the schema:`
    );
    for (const colName of diff.extraColumns) {
      statements.push(`-- ALTER TABLE ${diff.tableName} DROP COLUMN ${colName};`);
    }
  }

  // Handle column changes (NOT NULL, etc)
  if (diff.columnChanges) {
    for (const change of diff.columnChanges) {
      const field = Object.entries(schema.fields).find(
        ([name, candidate]) => (candidate.fieldName ?? name) === change.column,
      )?.[1];
      if (dialect === 'mysql' && field) {
        statements.push(
          `ALTER TABLE ${diff.tableName} MODIFY COLUMN ${change.column} ${
            change.current
              ? mysqlChangedColumnDefinition(field, change.current, change.change)
              : `${fieldTypeToSQL(field, dialect)} ${field.required ? 'NOT NULL' : 'NULL'}${schemaDefaultClause(field, dialect)}`
          };`,
        );
      } else {
        statements.push(
          `-- TODO: Handle column change for ${diff.tableName}.${change.column}: ${change.change}`
        );
      }
    }
  }

  for (const index of diff.missingIndexes ?? []) {
    statements.push(generateCreateIndexSQL(diff.tableName, index, dialect, schema));
  }
  for (const index of diff.changedIndexes ?? []) {
    statements.push(generateDropIndexSQL(diff.tableName, index.name, dialect));
    statements.push(generateCreateIndexSQL(diff.tableName, {
      name: index.name,
      ...index.required,
    }, dialect, schema));
  }

  return statements;
}

function generateCreateIndexSQL(
  tableName: string,
  index: { name: string; columns: string[]; unique: boolean; indexType?: string },
  dialect: Dialect,
  schema?: TableSchema,
  knownTextColumns: readonly string[] = [],
  knownPrefixLengths: readonly (number | null)[] = [],
  knownColumnMetadata: readonly (MySqlIndexColumnMetadata | null)[] = [],
): string {
  const ifNotExists = dialect === 'mysql' ? '' : 'IF NOT EXISTS ';
  const mysqlIndexType = dialect === 'mysql' && index.indexType
    ? index.indexType.toUpperCase()
    : '';
  if (
    mysqlIndexType &&
    !['BTREE', 'HASH', 'FULLTEXT', 'SPATIAL', 'RTREE'].includes(mysqlIndexType)
  ) {
    throw new Error(
      `Unsupported introspected MySQL index type for ${index.name}: ${index.indexType}`,
    );
import type {
  DatafnChangelogEntry,
  DatafnHydrationState,
  DatafnStorageAdapter,
} from "@datafn/client";
import {
  requestBridgeMethod,
  type DatafnBridgeBus,
  type NativeBridgeMarker,
} from "./protocol.js";

export function createNativeBackedStorageAdapter(
  bus: DatafnBridgeBus,
): DatafnStorageAdapter & NativeBridgeMarker {
  return {
    __datafnNativeBacked: true,
    capabilities: { atomicMergeIfMissing: true },
    getRecord(resource, id) {
      return requestBridgeMethod<Record<string, unknown> | null>(
        bus,
        "storage.getRecord",
        { resource, id },
      );
    },
    listRecords(resource) {
      return requestBridgeMethod<Record<string, unknown>[]>(
        bus,
        "storage.listRecords",
        { resource },
      );
    },
    upsertRecord(resource, record) {
      return requestBridgeMethod<void>(bus, "storage.upsertRecord", {
        resource,
        record,
      });
    },
    deleteRecord(resource, id) {
      return requestBridgeMethod<void>(bus, "storage.deleteRecord", {
        resource,
        id,
      });
    },
    mergeRecord(resource, id, partial, options) {
      return requestBridgeMethod<Record<string, unknown>>(
        bus,
        "storage.mergeRecord",
        { resource, id, partial, ...(options ? { options } : {}) },
      );
    },
    listJoinRows(relationKey) {
      return requestBridgeMethod<Array<Record<string, unknown>>>(
        bus,
        "storage.listJoinRows",
        { relationKey },
      );
    },
    getJoinRows(relationKey, fromId) {
      return requestBridgeMethod<Array<Record<string, unknown>>>(
        bus,
        "storage.getJoinRows",
        { relationKey, fromId },
      );
    },
    getJoinRowsInverse(relationKey, toId) {
      return requestBridgeMethod<Array<Record<string, unknown>>>(
        bus,
        "storage.getJoinRowsInverse",
        { relationKey, toId },
      );
    },
    upsertJoinRow(relationKey, row) {
      return requestBridgeMethod<void>(bus, "storage.upsertJoinRow", {
        relationKey,
        row,
      });
    },
    setJoinRows(relationKey, rows) {
      return requestBridgeMethod<void>(bus, "storage.setJoinRows", {
        relationKey,
        rows,
      });
    },
    deleteJoinRow(relationKey, from, to) {
      return requestBridgeMethod<void>(bus, "storage.deleteJoinRow", {
        relationKey,
        from,
        to,
      });
    },
    findRecords(resource, field, value) {
      return requestBridgeMethod<Record<string, unknown>[]>(
        bus,
        "storage.findRecords",
        { resource, field, value },
      );
    },
    getCursor(resource) {
      return requestBridgeMethod<string | null>(bus, "storage.getCursor", {
        resource,
      });
    },
    setCursor(resource, cursor) {
      return requestBridgeMethod<void>(bus, "storage.setCursor", {
        resource,
        cursor,
      });
    },
    getHydrationState(resource) {
      return requestBridgeMethod<DatafnHydrationState>(
        bus,
        "storage.getHydrationState",
        { resource },
      );
    },
    setHydrationState(resource, state) {
      return requestBridgeMethod<void>(bus, "storage.setHydrationState", {
        resource,
        state,
      });
    },
    changelogAppend(entry) {
      return requestBridgeMethod<DatafnChangelogEntry>(
        bus,
        "storage.changelogAppend",
        { entry },
      );
    },
    changelogList(options) {
      return requestBridgeMethod<DatafnChangelogEntry[]>(
        bus,
        "storage.changelogList",
        { options },
      );
    },
    changelogAck(options) {
      return requestBridgeMethod<void>(bus, "storage.changelogAck", {
        options,
      });
    },
    countRecords(resource) {
      return requestBridgeMethod<number>(bus, "storage.countRecords", {
        resource,
      });
    },
    countJoinRows(relationKey) {
      return requestBridgeMethod<number>(bus, "storage.countJoinRows", {
        relationKey,
      });
    },
    close() {
      return requestBridgeMethod<void>(bus, "storage.close");
    },
    clearAll() {
      return requestBridgeMethod<void>(bus, "storage.clearAll");
    },
    healthCheck() {
      return requestBridgeMethod<{ ok: boolean; issues: string[] }>(
        bus,
        "storage.healthCheck",
      );
    },
  };
}

