    }
  } else if (hasGuard) {
    // No transaction available: evaluate guard outside transaction (TOCTOU possible but rare)
    const guardResult = await evaluateGuard(
      db,
      mutation.resource,
      mutation.id,
      mutation.if!,
      schema,
